        "copy.heldBackNew": "{count, plural, one {# nouvelle carte pour plus tard — ton rythme du jour est atteint.} other {# nouvelles cartes pour plus tard — ton rythme du jour est atteint.}}",
        "copy.alreadySubscribed": "Tu es déjà abonné.",
        "legal.backHome": "Retour à l'accueil",
        "legal.eyebrow": "Micabo · iPhone et site",
        "legal.updated": "Dernière mise à jour : {date}.",
        "legal.updatedDate": "2 septembre 2026",
        "legal.privacy.metaTitle": "Confidentialité",
        "legal.privacy.metaDescription": "Ce que Micabo retient de vous, sur iPhone et sur le site, et ce que vous pouvez en faire.",
        "legal.privacy.heading": "Politique de confidentialité",
        "legal.privacy.linkLabel": "politique de confidentialité",
        "legal.privacy.intro1": "Cette politique décrit les données que Micabo traite lorsque vous utilisez le site [[site]] ou l'application iPhone (identifiant {bundle}). Les deux clients partagent le même compte et la même base. Elle s'applique aussi si vous n'avez pas encore de compte et que vous consultez le site.",
        "legal.privacy.intro2": "Le responsable du traitement est {editor}, qui édite Micabo. Pour toute question, correction ou suppression : [[contact]].",
        "legal.privacy.whatTitle": "Ce que Micabo est",
        "legal.privacy.whatBody": "Micabo transforme un cours (PDF, photo, document, vidéo) en fiche et en flashcards, puis les fait revenir avant que vous les oubliiez. Un mode examen resserre les révisions à l'approche d'une date. Vous pouvez partager un cours avec des amis, ou le garder pour vous.",
        "legal.privacy.dataTitle": "Quelles données nous traitons",
        "legal.privacy.dataAccount": "**Le compte.** Adresse e-mail, identifiants fournis par Apple ou Google si vous choisissez ces connexions, et un nom d'utilisateur. Nous ne stockons pas votre mot de passe : la connexion par courriel se fait par un lien, pas par un secret que nous garderions.",
        "legal.privacy.dataSchool": "**Le parcours scolaire.** Pays d'études, palier, matières, établissement si vous le donnez. Cela sert à écrire la fiche dans la bonne langue et le bon système, et à vous montrer les camarades du même établissement si un cours est partagé.",
        "legal.privacy.dataCourses": "**Vos cours.** Les fichiers ou liens que vous déposez, le texte qui en est extrait, les fiches et les cartes générées, les images de schémas, les examens (nom, date, note visée) et l'historique de révision (quand une carte revient, comment vous l'avez notée).",
        "legal.privacy.dataFriends": "**Les amis.** Les demandes d'ami, la liste de vos amis, et la visibilité que vous posez sur chaque cours au moment de l'import : vous seul, vos amis, ou les camarades de votre établissement. Il n'existe pas de catalogue public où un inconnu tomberait sur vos fiches.",
        "legal.privacy.dataSubscription": "**L'abonnement.** L'état de votre accès Pro (actif, essai, résilié), pas le numéro de votre carte. Le paiement est encaissé par Apple sur iPhone, par Stripe sur le site. RevenueCat tient le droit, pour que l'iPhone et le navigateur soient d'accord.",
        "legal.privacy.dataWaitlist": "**La liste d'attente.** Si vous laissez votre adresse avant d'avoir un compte, nous la gardons pour vous prévenir de l'ouverture, avec la page d'où vous venez. Elle n'est pas liée à un compte et n'est pas visible via l'application.",
        "legal.privacy.dataFeedback": "**Les retours.** Si vous envoyez un bug ou une idée depuis l'app, nous gardons le message, le type (bug ou idée), et le lien avec votre compte, pour y répondre. Ils restent 24 mois, puis sont effacés. Ils ne servent pas à vous profiler.",
        "legal.privacy.dataUsage": "**L'usage des générations.** Un compteur par jour et par fonction (fiche, cartes, explication), sans le contenu du cours. Il sert à limiter les abus, pas à vous profiler.",
        "legal.privacy.dataDirectory": "**L'annuaire.** Votre nom d'utilisateur et, si vous l'avez indiqué, votre établissement. C'est ce que voient un ami ou un camarade, pas votre e-mail ni vos préférences.",
        "legal.privacy.dataDevice": "**Ce qui reste sur l'appareil.** Sur iPhone, certaines pièces (images d'occlusion, audio d'une carte) peuvent ne jamais quitter le téléphone. Les réponses du parcours d'accueil restent d'abord sur l'appareil, puis sont écrites en base une fois le compte ouvert.",
        "legal.privacy.dataNoSell": "Nous ne vendons pas vos données. Nous n'affichons pas de publicité. Nous n'entraînons pas un modèle de langage sur vos cours, sauf si un réglage explicite le propose un jour — et ce réglage n'existe pas aujourd'hui.",
        "legal.privacy.whyTitle": "Pourquoi nous les traitons",
        "legal.privacy.whyLead": "Les bases légales, au sens du RGPD :",
        "legal.privacy.whyContract": "**L'exécution du contrat** — créer le compte, importer un cours, écrire la fiche et les cartes, les réviser, synchroniser iPhone et site, gérer l'abonnement.",
        "legal.privacy.whyLegitimate": "**L'intérêt légitime** — sécuriser le service, empêcher les abus, diagnostiquer une panne, mesurer l'audience du site de façon agrégée, et lire les retours que vous nous envoyez. Cet intérêt ne passe pas avant le vôtre : le cloisonnement est dans la base, pas seulement dans l'application.",
        "legal.privacy.whyLegal": "**L'obligation légale** — conserver ce que la facturation ou la comptabilité exigent, le temps prescrit.",
        "legal.privacy.whyConsent": "**Le consentement** — quand vous choisissez de partager un cours, d'ouvrir l'appareil photo, ou de vous connecter avec Apple ou Google.",
        "legal.privacy.accessTitle": "Qui y a accès",
        "legal.privacy.accessBody": "Vos cours ne sont lisibles que par vous, sauf si vous les avez partagés. Chaque requête à la base est évaluée avec votre identité : il n'existe pas de requête qui puisse demander les cours de quelqu'un d'autre. Les retours que vous envoyez sont lus par l'équipe, à l'adresse [[contact]]. Personne d'autre n'y a accès depuis l'application.",
        "legal.privacy.accessLead": "Des prestataires voient une partie des données, uniquement pour fournir le service :",
        "legal.privacy.accessSupabase": "**Supabase** (Union européenne, région Stockholm) — compte, base, fichiers.",
        "legal.privacy.accessVercel": "**Vercel** — hébergement du site, journaux techniques (adresse IP, URL) et mesure d'audience : le nombre de pages vues, la page d'où vous venez, le pays et le type d'appareil, sans cookie et sans identifiant qui vous suive. Le traitement peut avoir lieu hors de l'Union européenne, sous les clauses contractuelles types du prestataire.",
        "legal.privacy.accessApple": "**Apple et Google** — si vous vous connectez avec eux, ou si vous payez sur l'App Store.",
        "legal.privacy.accessStripe": "**Stripe** — paiement sur le site.",
        "legal.privacy.accessRevenuecat": "**RevenueCat** — état de l'abonnement, partagé entre iPhone et site.",
        "legal.privacy.accessFal": "**fal.ai et les modèles qu'il appelle** (aujourd'hui, des modèles de langage, notamment de Google) — le texte ou l'image de votre cours, le temps d'écrire la fiche ou les cartes. Ils n'ont pas le droit de s'en servir pour autre chose que cette génération.",
        "legal.privacy.accessYoutube": "**YouTube / Google** — si vous importez une vidéo, nous en lisons les métadonnées et les sous-titres.",
        "legal.privacy.accessTransfer": "Certains de ces prestataires sont établis hors de l'Union européenne. Le transfert n'a alors lieu que pour fournir le service, et s'appuie sur les garanties prévues par le RGPD (décision d'adéquation ou clauses contractuelles types du prestataire).",
        "legal.privacy.cookiesTitle": "Cookies et traceurs",
        "legal.privacy.cookiesWeb": "Le site pose les cookies nécessaires à la session (vous reconnaître d'une page à l'autre une fois connecté) et un cookie de préférence de langue d'interface (`micabo.ui_locale`), gardé un an, qui retient l'anglais, le français, l'allemand, l'espagnol ou le turc. Nous ne posons pas de cookie de mesure d'audience, ni de publicité, ni de pistage inter-sites. Le site compte bien ses visites, mais sans rien écrire sur votre appareil : la mesure retient une page vue, sa provenance, un pays, un type d'appareil, et rien qui permette de vous reconnaître d'une visite à l'autre ou sur un autre site. C'est pour cela qu'il n'y a pas de bandeau de consentement : il n'y a rien à refuser de ce côté-là.",
        "legal.privacy.cookiesIos": "L'iPhone n'utilise pas de cookies. Il garde un jeton de session dans le trousseau de l'appareil.",
        "legal.privacy.retentionTitle": "Combien de temps nous les gardons",
        "legal.privacy.retentionWhile": "Tant que le compte existe. Les retours partent au plus tard au bout de 24 mois. Si vous le supprimez, depuis Réglages sur le site ou dans l'app iPhone, ou en nous écrivant, nous effaçons le profil, les cours (y compris le texte extrait), les fiches, les cartes, l'historique, les examens, les amitiés, les compteurs d'usage, les retours et l'adresse éventuellement laissée sur la liste d'attente.",
        "legal.privacy.retentionShared": "Un cours que vous avez partagé disparaît pour vos amis quand vous le supprimez. Un ami qui a déjà révisé vos cartes conserve son propre historique, pas votre document.",
        "legal.privacy.retentionAfter": "Après suppression, il reste chez des prestataires ce que la loi ou leur contrat impose : factures Stripe ou Apple, identifiant d'abonnement RevenueCat, journaux techniques (Vercel, Supabase) quelques semaines. fal.ai reçoit le texte le temps d'écrire la fiche ; nous ne lui demandons pas de le conserver.",
        "legal.privacy.rightsTitle": "Vos droits",
        "legal.privacy.rightsBody": "Vous pouvez accéder à vos données, les corriger, les exporter, vous opposer à un traitement, ou demander l'effacement. Pour télécharger une copie : Réglages → « Télécharger mes données ». Pour effacer le compte : Réglages → « Supprimer le compte », sur le site ou dans l'app iPhone. Vous pouvez aussi écrire à [[contact]]. Nous répondons dans le mois.",
        "legal.privacy.rightsCnil": "Vous pouvez aussi introduire une réclamation auprès de la CNIL (cnil.fr).",
        "legal.privacy.minorsTitle": "Mineurs",
        "legal.privacy.minorsBody": "Micabo s'adresse à des étudiants, y compris au lycée. Nous ne demandons pas la date de naissance. Si vous avez moins de quinze ans, l'usage du service doit se faire avec l'accord d'un titulaire de l'autorité parentale. Nous n'utilisons pas les données d'un mineur pour de la publicité, ni pour un profilage commercial.",
        "legal.privacy.iosTitle": "L'iPhone, en plus du site",
        "legal.privacy.iosBody": "L'app peut demander l'accès à vos photos ou à l'appareil photo pour importer un cours. Ce n'est pas obligatoire : le site accepte un fichier déposé. Les notifications, si vous les autorisez, ne servent qu'à vous rappeler une révision. Le même compte ouvre l'app et le site.",
        "legal.privacy.changesTitle": "Modifications",
        "legal.privacy.changesBody": "Si cette politique change de façon substantielle, nous mettons à jour la date en tête de page. L'usage continu après cette date vaut pour la nouvelle version, sauf si la loi exige un accord distinct.",
        "legal.privacy.changesAlso": "Les [[terms]] complètent ce texte.",
        "legal.terms.metaTitle": "Conditions d'utilisation",
        "legal.terms.metaDescription": "Les règles du service Micabo, pour l'iPhone et le site : compte, cours, abonnement, responsabilités.",
        "legal.terms.heading": "Conditions d'utilisation",
        "legal.terms.linkLabel": "conditions d'utilisation",
        "legal.terms.intro1": "Ces conditions régissent l'usage de Micabo — le site [[site]] et l'application iPhone ({bundle}). En créant un compte ou en utilisant le service, vous les acceptez. Si vous n'êtes pas d'accord, n'ouvrez pas de compte.",
        "legal.terms.intro2": "L'éditeur est {editor}. Contact : [[contact]].",
        "legal.terms.serviceTitle": "Le service",
        "legal.terms.serviceBody": "Micabo lit un document de cours que vous déposez et en écrit une fiche et des flashcards. Il les fait revenir selon une répétition espacée (la même règle SM-2 sur iPhone et sur le site). Vous pouvez poser la date d'un examen : le plan de révision se resserre alors vers ce jour. Un même compte ouvre les deux clients.",
        "legal.terms.servicePro": "Une partie du service est accessible sans abonnement. L'accès Pro (cours et cartes au-delà du plafond gratuit, selon l'offre affichée au moment de l'achat) est payant.",
        "legal.terms.accountTitle": "Le compte",
        "legal.terms.accountBody": "Vous pouvez vous connecter avec Apple, Google, ou un lien envoyé par courriel. Vous êtes responsable de l'accès à votre boîte mail et à ces comptes tiers. Un seul compte par personne.",
        "legal.terms.accountDelete": "Vous pouvez supprimer le compte depuis Réglages, sur le site ou dans l'app iPhone. Cela efface vos cours, vos cartes et votre historique. Les achats déjà encaissés par Apple ou Stripe restent soumis à leurs règles de remboursement.",
        "legal.terms.coursesTitle": "Vos cours",
        "legal.terms.coursesOwn": "Vous gardez la propriété de ce que vous déposez. Vous nous donnez seulement le droit, limité et révocable, de le lire, de le stocker et de le transformer en fiche et en cartes, pour vous fournir le service — y compris en l'envoyant à un modèle de langage le temps de la génération.",
        "legal.terms.coursesRights": "Vous ne déposez que des documents que vous avez le droit d'utiliser. Un polycopié de votre professeur, vos notes, une vidéo dont l'import est autorisé : oui. Un ouvrage entier recopié, le devoir d'un autre, un contenu illégal : non. Nous pouvons retirer un cours ou fermer un compte qui casse cette règle.",
        "legal.terms.coursesShare": "La visibilité se décide à l'import. Un cours privé reste entre vous. Un cours partagé n'est visible que par les personnes que vous avez choisies (amis, ou camarades de l'établissement). Ce n'est pas une bibliothèque ouverte à tous.",
        "legal.terms.notTitle": "Ce que Micabo n'est pas",
        "legal.terms.notBody": "La fiche et les cartes sont générées automatiquement. Elles peuvent se tromper, omettre un passage, ou mal lire un scan. Micabo n'est pas un professeur, ni une garantie de note. Vous restez responsable de ce que vous apprenez et de ce que vous rendez le jour de l'examen.",
        "legal.terms.notInvent": "Nous nous efforçons de ne pas inventer une définition quand le document ne la porte pas. Ça ne rend pas le résultat infaillible.",
        "legal.terms.subTitle": "L'abonnement",
        "legal.terms.subPrices": "Les prix, la durée et l'essai éventuel sont ceux affichés avant le paiement. Ils peuvent changer pour les nouveaux achats ; un abonnement déjà en cours garde ses conditions jusqu'à son renouvellement.",
        "legal.terms.subIos": "**Sur iPhone**, le paiement passe par l'App Store. La résiliation, le renouvellement et les remboursements suivent les règles d'Apple. Gérez l'abonnement dans les réglages de votre compte Apple.",
        "legal.terms.subWeb": "**Sur le site**, le paiement passe par Stripe. La résiliation se fait depuis l'espace de facturation indiqué dans le profil, ou en nous écrivant. Un essai, s'il est proposé, ne se transforme en paiement que si vous le laissez aller à son terme.",
        "legal.terms.subBoth": "L'accès Pro acheté d'un côté vaut de l'autre : le même compte est Pro sur iPhone et sur le site. Un incident de paiement peut ouvrir une période de grâce ; nous ne fermons pas l'accès à la première heure.",
        "legal.terms.forbidTitle": "Ce que vous ne faites pas",
        "legal.terms.forbidHarm": "Utiliser le service pour nuire à quelqu'un, harceler, ou tricher d'une façon qui viole le règlement de votre établissement.",
        "legal.terms.forbidAccess": "Tenter d'accéder aux cours d'un autre compte, de contourner le cloisonnement, ou de surcharger volontairement le service.",
        "legal.terms.forbidResell": "Revendre l'accès, extraire le service par un robot au-delà d'un usage humain normal, ou copier Micabo pour en faire un produit concurrent à partir de nos générations.",
        "legal.terms.forbidIllegal": "Déposer des contenus illégaux, haineux, ou qui portent atteinte à la vie privée d'autrui.",
        "legal.terms.availTitle": "Disponibilité",
        "legal.terms.availBody": "Nous faisons notre possible pour que iPhone et site restent joignables. Une maintenance, une panne d'un prestataire (hébergeur, modèle, boutique) ou une erreur de génération peut interrompre le service. Nous n'offrons pas de garantie de résultat scolaire, ni de disponibilité ininterrompue.",
        "legal.terms.liabilityTitle": "Responsabilité",
        "legal.terms.liabilityConsumer": "Si vous êtes un consommateur, vos droits légaux (garantie, médiation, clauses abusives) s'appliquent et ces conditions ne les écartent pas.",
        "legal.terms.liabilityLimit": "Au-delà, Micabo n'est pas responsable des notes obtenues, d'une fiche incomplète, d'un oubli le jour J, ou d'un dommage indirect (temps perdu, examen manqué). Notre responsabilité, si elle était retenue pour un manquement qui nous est imputable, est limitée au montant que vous nous avez versé au cours des douze derniers mois — sauf faute lourde, dol, ou atteinte à l'intégrité de la personne.",
        "legal.terms.minorsTitle": "Mineurs",
        "legal.terms.minorsBody": "Si vous avez moins de quinze ans, un titulaire de l'autorité parentale doit accepter ces conditions et surveiller l'usage. Le partage d'un cours avec des amis reste sous votre responsabilité, et sous la leur.",
        "legal.terms.lawTitle": "Droit applicable",
        "legal.terms.lawBody": "Ces conditions sont régies par le droit français. En cas de litige, et après une tentative de résolution écrite à [[contact]], les tribunaux français sont compétents — sous réserve des règles de protection du consommateur qui vous seraient plus favorables.",
        "legal.terms.changesTitle": "Modifications",
        "legal.terms.changesBody": "Nous pouvons mettre à jour ces conditions. La date en tête de page fait foi. Un changement qui touche au prix d'un abonnement en cours vous est annoncé avant le renouvellement.",
        "legal.terms.changesAlso": "La [[privacy]] décrit le traitement de vos données.",
        "articles.shared.navAria": "Pages",
        "articles.shared.nextTitle": "À lire ensuite",
        "articles.shared.ctaTitle": "Dépose un cours, regarde ce qu'il devient.",
        "articles.shared.ctaBody": "Le premier est gratuit, sur le site comme sur iPhone.",
        "articles.method.metaTitle": "La méthode : répétition espacée et rappel actif",
        "articles.method.metaDescription": "Relire un cours ne le fait pas retenir. Ce qu'on retrouve de mémoire tient, surtout si la question revient juste avant l'oubli. Comment Micabo applique la répétition espacée, avec les vrais intervalles.",
        "articles.method.h1": "Relire ne suffit pas. Se souvenir, oui.",
        "articles.method.lead1": "Une page relue quatre fois donne une impression de maîtrise qui ne survit pas à la copie double. C'est la reconnaissance qui progresse — « oui, j'ai déjà vu ça » — et la reconnaissance n'est pas ce qu'un examen demande.",
        "articles.method.lead2": "Ce qui tient, c'est ce qu'on a dû **retrouver de mémoire**, et ce qui revient **juste avant qu'on l'oublie**. Deux idées anciennes, mesurées depuis plus d'un siècle, et deux idées pénibles à appliquer à la main. C'est tout le travail de Micabo.",
        "articles.method.activeTitle": "Le rappel actif : la question avant la réponse",
        "articles.method.active1": "Se tester est plus efficace que relire, même quand on se trompe. L'effort de récupération est ce qui renforce la trace : une réponse qu'on cherche pendant trois secondes vaut mieux qu'une réponse qu'on lit en une.",
        "articles.method.active2": "C'est aussi pour ça qu'une flashcard porte **une seule chose à retrouver**. Une carte qui demande cinq éléments d'un coup ne se note pas : on en retrouve trois, et il n'existe pas de bouton pour « trois cinquièmes ».",
        "articles.method.spacingTitle": "L'espacement : revenir au dernier moment utile",
        "articles.method.spacing1": "Sans révision, ce qu'on retient d'un cours tombe à presque rien en un mois. Chaque rappel remet le compteur à cent — et la descente qui suit est **plus lente que la précédente**. Réviser au bon moment ne demande donc pas plus de temps : ça en demande moins, à mesure que la mémoire se stabilise.",
        "articles.method.spacing2": "L'intérêt n'est pas la forme de chaque courbe, c'est **l'endroit où elles se séparent** : la première révision. Ce que la répétition espacée automatise, c'est le choix de cet instant, carte par carte.",
        "articles.method.plannerTitle": "Ce que Micabo calcule à chaque note",
        "articles.method.planner1": "Micabo planifie en **SM-2**, la règle d'Anki dans ses réglages par défaut. Une carte neuve passe par des paliers courts — {steps} — avant de sortir en jours. Ensuite, chaque note multiplie l'intervalle par une facilité propre à la carte, qui part de {ease} et bouge selon tes réponses.",
        "articles.method.planner2": "Quatre boutons, pas deux : « je sais / je ne sais pas » ne distingue pas la carte retrouvée avec peine de celle qui est venue seule, et c'est justement cet écart qui décide de la date suivante. Voici ce que les quatre boutons annoncent sur une carte neuve :",
        "articles.method.planner3": "L'intervalle est écrit sur le bouton **avant** qu'on appuie. Un planificateur qui décide dans son coin se fait vite désobéir : on note « facile » pour aller plus vite, la carte repart à trois semaines, et on la redécouvre le jour de l'épreuve.",
        "articles.method.stepMinutes": "{n} min",
        "articles.method.stepJoin": ", puis ",
        "articles.method.paceTitle": "Le rythme : des minutes, pas un quota de cartes",
        "articles.method.pace1": "Le réglage que Micabo demande est un temps par jour, pas un nombre de cartes. À {minutes} minutes — le défaut — on voit environ {seen} cartes, et le produit n'en introduit que **{perDay} neuves**.",
        "articles.method.pace2": "L'écart entre les deux est le cœur du réglage : une carte neuve ne coûte pas un passage, elle en coûte environ {reps} avant d'être acquise. Introduire cinquante cartes aujourd'hui parce qu'on a le temps, c'est se poser une dette de sessions pour les trois semaines suivantes — et c'est comme ça qu'on abandonne un paquet.",
        "articles.method.paceNote": "Le plafond du jour ne bloque pas les révisions dues : celles-là passent toutes. Il ne rationne que l'introduction de nouvelles cartes. Une journée manquée ne crée donc pas de trou, elle décale.",
        "articles.method.sheetTitle": "La fiche d'abord, les cartes ensuite",
        "articles.method.sheet1": "Une flashcard suppose qu'on a déjà compris. Se tester sur une notion qu'on n'a pas lue, c'est apprendre une réponse par cœur sans savoir de quoi elle parle — la carte tombera juste, et l'examen non.",
        "articles.method.sheet2": "C'est pourquoi Micabo écrit d'abord **la fiche** à partir de ton document : le cours remis dans l'ordre, les passages qui comptent marqués. Les cartes sont tirées de cette fiche, pas du document brut. Tu lis, puis tu te testes.",
        "articles.method.sheet3": "Micabo ne définit jamais un terme dont le document ne parle pas. Quand le contexte ne tranche pas, le mot douteux n'apparaît pas dans la fiche : une définition inventée est parfaitement crédible, et c'est ce qui la rend dangereuse.",
        "articles.method.limitsTitle": "Ce que la méthode ne fait pas",
        "articles.method.limits1": "La répétition espacée place les révisions. Elle ne comprend pas à ta place, elle ne rédige pas une dissertation, et elle ne rattrape pas un chapitre commencé la veille — il n'y a pas d'espacement possible sur une nuit.",
        "articles.method.limits2": "Elle ignore aussi les dates, par construction : SM-2 ne sait pas qu'un examen a lieu dans trois semaines. C'est exactement ce que le [[exam]] vient corriger.",
        "articles.method.examLink": "mode examen",
        "articles.exam.metaTitle": "Le mode examen : donne la date, le plan se resserre",
        "articles.exam.metaDescription": "La répétition espacée ignore le jour J. Le mode examen de Micabo lui donne une date butoir, resserre les passages à l'approche de l'épreuve, et empêche une carte de repartir au-delà.",
        "articles.exam.h1": "Tu donnes la date. Micabo réorganise tout.",
        "articles.exam.lead1": "La répétition espacée place chaque carte au dernier moment utile, indéfiniment. Elle ne sait pas qu'il y a un partiel le 14. Une carte notée « facile » aujourd'hui repart à trois semaines, même si l'épreuve est dans dix jours — et elle ne reviendra pas avant.",
        "articles.exam.lead2": "Le mode examen donne au planificateur ce qui lui manque : **une date butoir**. Tu poses le jour J, il replanifie le paquet autour.",
        "articles.exam.trapTitle": "Pourquoi un planning normal se fait piéger",
        "articles.exam.trap1": "Un paquet de deux cents cartes en révision espacée est parfait pour un contrôle continu et mauvais pour une date fixe. Trois choses vont de travers : des cartes tombent après l'examen, d'autres n'ont jamais été introduites, et les plus fragiles reviennent trop tôt pour être utiles le jour J.",
        "articles.exam.trap2": "La réponse manuelle consiste à réviser tout le paquet la veille. C'est exactement ce que la méthode évite : une session de trois cents cartes en une soirée ne laisse rien le lendemain, et on le sait avant de commencer.",
        "articles.exam.capTitle": "Aucune carte ne repart au-delà du jour J",
        "articles.exam.cap1": "C'est la règle qui fait tout tenir, et elle est plus radicale qu'elle en a l'air. Pendant un examen actif, l'intervalle qu'une carte reçoit est **plafonné à la date de l'épreuve**.",
        "articles.exam.cap2": "Sans ce plafond, la première bonne réponse défait le plan : la carte s'en va à trois semaines et sort du champ. Avec lui, elle revient une dernière fois avant le jour J. Les intervalles annoncés sous les boutons sont donc plus courts que d'habitude, et la session le dit en haut de l'écran — sinon on croirait le planificateur cassé.",
        "articles.exam.planTitle": "Le plan, annoncé avant d'être appliqué",
        "articles.exam.plan1": "Micabo montre la projection **avant** de déplacer quoi que ce soit : combien de cartes sont couvertes, combien de passages sont placés, sur combien de jours. Une replanification qu'on découvre après coup est une replanification qu'on annule.",
        "articles.exam.plan2": "La charge se resserre vers la fin sans s'empiler sur la veille : les derniers passages s'étalent sur les {days} derniers jours, décalés d'une carte à l'autre.",
        "articles.exam.intensityTitle": "Trois intensités, selon la note que tu veux",
        "articles.exam.intensityLead": "Combien de fois chaque carte doit repasser avant l'épreuve n'est pas la même question pour « je veux valider » et pour « je veux le major ». Tu poses la note visée, Micabo en déduit l'intensité :",
        "articles.exam.intensityLight": "Légère",
        "articles.exam.intensityStandard": "Normale",
        "articles.exam.intensityIntense": "Intensive",
        "articles.exam.intensityPasses": "passages par carte",
        "articles.exam.intensityScale": "L'échelle de notes suit ton pays de scolarisation : un 20 français, un 100 québécois et un A-Level britannique ne se comparent pas, et un curseur qui vaudrait partout ne voudrait rien dire nulle part.",
        "articles.exam.severalTitle": "Plusieurs examens, plusieurs cours",
        "articles.exam.several1": "Un examen porte sur les cours que tu lui donnes, et un cours peut être dans plusieurs examens. Quand deux dates se disputent une même carte, c'est **la plus proche** qui plafonne : elle est la première contrainte, et respecter la seconde d'abord raterait les deux.",
        "articles.exam.severalNote": "Passé le jour J, l'examen cesse de contraindre et le paquet revient à sa planification normale. Rien à désactiver : une date passée n'est plus une date.",
        "articles.exam.limitsTitle": "Ce que le mode examen ne fait pas",
        "articles.exam.limits1": "Il ne fabrique pas du temps. Déclarer un examen pour demain sur deux cents cartes neuves donne un plan honnête et intenable, et Micabo l'affiche tel quel plutôt que de rassurer.",
        "articles.exam.limits2": "Il ne remplace pas non plus la méthode : [[method]] font le travail, le mode examen ne fait que leur donner une échéance. Si tu viens d'Anki, la [[anki]] dit précisément ce que ça change.",
        "articles.exam.methodLink": "le rappel actif et l'espacement",
        "articles.exam.ankiLink": "comparaison",
        "articles.anki.metaTitle": "Micabo ou Anki : ce qui change vraiment",
        "articles.anki.metaDescription": "Anki est gratuit, ouvert et excellent. Micabo écrit les cartes à partir de ton cours et replanifie tout autour d'une date d'examen. Comparaison honnête, y compris là où Anki gagne.",
        "articles.anki.eyebrow": "Comparaison",
        "articles.anki.h1": "Micabo ou Anki : ce qui change vraiment",
        "articles.anki.lead1": "Anki est un très bon logiciel. Il est gratuit, ouvert, il a vingt ans de recul et une communauté qui a tout documenté. Si tu t'en sers déjà et que ça te va, tu n'as aucune raison d'en changer.",
        "articles.anki.lead2": "La différence n'est pas dans la planification — **c'est le même SM-2**. Elle est avant, dans le temps qu'il faut pour avoir des cartes, et après, dans ce qui arrive quand une date d'examen tombe.",
        "articles.anki.tableTitle": "Ligne par ligne",
        "articles.anki.tableLead": "Trois lignes vont à Anki, dont la plus importante pour beaucoup de gens : il ne coûte rien.",
        "articles.anki.tableCaption": "Comparaison de Micabo et d'Anki, critère par critère.",
        "articles.anki.colCriterion": "Critère",
        "articles.anki.rowAlgo": "L'algorithme",
        "articles.anki.rowAlgoMicabo": "SM-2, avec les réglages par défaut d'Anki.",
        "articles.anki.rowAlgoAnki": "SM-2 historiquement, FSRS aujourd'hui, et les deux se règlent.",
        "articles.anki.rowWrite": "Écrire les cartes",
        "articles.anki.rowWriteMicabo": "Le cours devient une fiche, la fiche devient des cartes. Tu relis et tu corriges.",
        "articles.anki.rowWriteAnki": "À toi. C'est là que passe l'essentiel du temps.",
        "articles.anki.rowDate": "Une date d'examen",
        "articles.anki.rowDateMicabo": "Le paquet se replanifie autour du jour J, et rien ne repart au-delà.",
        "articles.anki.rowDateAnki": "Pas de notion de date butoir. On avance le paquet à la main.",
        "articles.anki.rowPrice": "Le prix",
        "articles.anki.rowPriceMicabo": "Un cours gratuit, {cards} cartes par session. Au-delà, {price} par an.",
        "articles.anki.rowPriceAnki": "Gratuit et open source, sauf l'app iPhone.",
        "articles.anki.rowPlatforms": "Les plateformes",
        "articles.anki.rowPlatformsMicabo": "iPhone et navigateur, le même compte des deux côtés.",
        "articles.anki.rowPlatformsAnki": "Ordinateur, Android, iPhone, navigateur.",
        "articles.anki.rowDecks": "Les paquets tout faits",
        "articles.anki.rowDecksMicabo": "Aucun catalogue. Tes cours, et ceux que tes amis partagent.",
        "articles.anki.rowDecksAnki": "Des milliers de paquets publics, de qualité inégale.",
        "articles.anki.rowFriends": "Les cours de tes camarades",
        "articles.anki.rowFriendsMicabo": "Un cours partagé se reprend en un geste, et devient le tien.",
        "articles.anki.rowFriendsAnki": "Un fichier à s'envoyer.",
        "articles.anki.rowStart": "La mise en route",
        "articles.anki.rowStartMicabo": "Un document déposé, une fiche à lire, une session le soir même.",
        "articles.anki.rowStartAnki": "Des réglages à comprendre avant la première carte.",
        "articles.anki.costTitle": "Le coût d'Anki n'est pas son prix",
        "articles.anki.cost1": "Un paquet Anki utile pour un cours de fac, c'est deux à quatre heures de saisie par chapitre : découper, formuler une question par idée, ne pas empiler cinq éléments sur une carte. Ce travail est instructif — le nier serait malhonnête — mais c'est le travail qui fait qu'on ouvre Anki en septembre et plus en novembre.",
        "articles.anki.cost2": "Micabo prend cette étape. Le cours devient une fiche remise dans l'ordre, puis des cartes tirées de cette fiche. Tu relis, tu corriges ce qui est faux, tu supprimes ce qui ne sert pas. Ça reste ton travail, mais il commence à la relecture au lieu de commencer à la page blanche.",
        "articles.anki.costNote": "Le revers est réel : une carte générée peut être mal formulée ou tirée d'un scan mal lu. C'est pour ça que la fiche vient avant les cartes, et que Micabo ne définit pas un terme dont le document ne parle pas. Une fiche qui se trompe ne ressemble pas à une erreur.",
        "articles.anki.dateTitle": "Ce qu'Anki ne fait pas : la date",
        "articles.anki.date1": "C'est la vraie différence de mécanique. La répétition espacée place chaque carte au dernier moment utile, sans fin. Elle ne sait pas qu'il y a un partiel le 14 : une carte notée « facile » repart à trois semaines et ne revient pas avant l'épreuve.",
        "articles.anki.date2": "Dans Anki, on s'en sort en avançant le paquet à la main, ou en révisant tout la veille. Dans Micabo, tu poses la date et le paquet se replanifie autour, avec un plafond qui empêche une carte de repartir au-delà du jour J. [[exam]] détaille comment.",
        "articles.anki.examLink": "Le mode examen",
        "articles.anki.pickTitle": "Lequel prendre",
        "articles.anki.pickAnki": "**Reste sur Anki** si tu aimes régler ton planificateur, si tu veux FSRS, si tu es sur Android, ou si tu tiens à un outil gratuit et ouvert dont tu possèdes les fichiers.",
        "articles.anki.pickMicabo": "**Essaie Micabo** si ce qui te bloque n'est pas la révision mais la fabrication des cartes, ou si tes révisions sont organisées autour de dates d'examen plutôt que d'un flux continu.",
        "articles.anki.pickBoth": "Et si tu hésites : [[method]] est la même dans les deux. C'est elle qui fait le travail, pas le logiciel qui la porte.",
        "articles.anki.methodLink": "la méthode",
    ]

