        "landing.navAria": "Abschnitte",
        "landing.badge": "Skripte und Karteikarten, aus deinen Unterlagen",
        "landing.titleBefore": "Lerne alles,",
        "landing.titleAccent": "schneller",
        "landing.metaTitle": "Micabo - lerne alles, schneller",
        "landing.siteTitle": "Micabo - Blätter und Karteikarten aus deinem Stoff",
        "landing.metaDescription": "Leg ein Skript, ein Foto deiner Notizen oder ein Vorlesungsvideo ab. Micabo schreibt das Blatt, das du nachliest, zieht die Karten, die es dir merken lassen, und holt sie zurück, kurz bevor du es vergisst.",
        "landing.ogDescription": "Dein Stoff wird ein Blatt zum Nachlesen, und Karten, die im richtigen Moment zurückkommen. Im Web und auf dem iPhone.",
        "landing.ogDescriptionShort": "Dein Stoff wird ein Blatt zum Nachlesen, und Karten, die im richtigen Moment zurückkommen.",
        "landing.schemaDescription": "Micabo macht aus einem Kurs ein Blatt und Karteikarten, und holt sie per Spaced Repetition zurück.",
        "landing.manifestDescription": "Leg einen Kurs ab. Micabo schreibt das Blatt, zieht die Karten und holt sie zurück, bevor du vergisst.",
        "landing.subtitle": "Leg ein Skript, ein Foto deiner Notizen oder ein Vorlesungsvideo ab. Micabo schreibt das Blatt, zieht die Karten und holt sie zurück, kurz bevor du vergisst.",
