        "landing.cardsNote": "Vier Arten, denselben Stoff zu wiederholen. Tippen: die Rückseite ist da.",
        "landing.methodEyebrow": "Warum es hält",
        "landing.methodTitle": "Lesen reicht nicht. Erinnern schon.",
        "landing.methodNote": "Was du aus dem Gedächtnis holen musstest, bleibt - vor allem, wenn es zur richtigen Zeit wiederkommt, immer seltener.",
        "landing.methodMore": "Die Methode im Detail",
        "landing.examEyebrow": "Prüfungsmodus",
        "landing.examTitle": "Du nennst das Datum. Micabo plant neu.",
        "landing.examNote": "Die Wiederholung kennt keinen Stichtag. Der Prüfungsmodus gibt ihm eine Frist und zieht die Karten vor der Klausur zusammen.",
        "landing.examMore": "Wie der Plan enger wird",
        "landing.questionsEyebrow": "Fragen",
        "landing.questionsTitle": "Was uns gefragt wird.",
        "landing.questionsMore": "Micabo oder Anki: der Vergleich",
        "landing.closingTitle": "Deine nächste Klausur fängt jetzt an.",
        "landing.savePercent": "Spar {pct} %",
        "landing.pricingFeatures": "Kurse und Karten ohne Limit, Prüfungsmodus, und das ganze Blatt.",
        "landing.pricingTrial": "{days} Tage geschenkt.",
        "landing.pricingNoTrial": "Ohne Probe.",
        "landing.pricingFreeEyebrow": "Ohne zu zahlen",
        "landing.pricingFreeLead": "Ein ganzer Kurs zum Importieren",
        "landing.pricingFreeBody": ", von dem du {sheet} % des Blatts liest, und {cards} Karten pro Sitzung. Genug, um Micabo an deinem eigenen Stoff zu sehen, bevor du irgendetwas entscheidest - das ist die einzige Probe, die etwas bedeutet.",
        "landing.pricingNotOpen": "Das Abo ist noch nicht offen. Wir schreiben dir am Stichtag.",
        "landing.footerTagline": "Aus deinem Stoff wird ein Blatt zum Lesen und Karten, die zur richtigen Zeit wiederkommen.",
        "landing.footerProduct": "Das Produkt",
        "landing.footerSite": "Die Seite",
        "landing.footerRead": "Zum Lesen",
        "landing.footerLegal": "Der Rahmen",
        "landing.faq1q": "Sind meine Kurse privat?",
        "landing.faq1a": "Ja. Deine Kurse stehen in keinem Katalog. Es gibt kein « Entdecken », wo ein Fremder auf deine Blätter stößt: das bleibt zwischen dir und deinen Freunden. Standardmäßig siehst du sie allein. Beim Import kannst du einen teilen - mit Freunden oder mit niemandem - und die Entscheidung fällt in diesem Moment, nicht hinterher. Die Trennung sitzt in der Datenbank: jede Anfrage läuft mit deiner Identität, es gibt also keine Anfrage, die die Kurse eines anderen holen kann.",
        "landing.faq2q": "Erfindet Micabo Dinge?",
        "landing.faq2a": "Das nehmen wir am ernstesten, weil ein falsches Blatt nicht wie ein Fehler aussieht. Ein schlecht gelesenes Wort kann eine völlig glaubhafte und völlig falsche Definition ergeben. Micabo definiert deshalb nie einen Begriff, dessen es sich nicht sicher ist: wenn der Kontext nicht reicht, erscheint das zweifelhafte Wort einfach nicht auf dem Blatt.",
        "landing.faq3q": "Geht das in anderen Sprachen? Anderen Schulsystemen?",
        "landing.faq3a": "Ja. Das Land der Schule bestimmt das Bezugssystem und die Sprache der Blätter. Die Seite selbst liest sich auf Englisch, Französisch, Deutsch, Spanisch oder Türkisch: du wechselst die Sprache oben auf der Seite, im Einstieg oder in den Einstellungen. iPhone und Browser teilen die Sprache der Blätter.",
        "landing.faq4q": "Was passiert nach der Probezeit?",
        "landing.faq4a": "Die {days} Probetage enden, und es wird nichts abgebucht, ohne dass du es entschieden hast. Kurse und Karten bleiben, auf der Seite wie auf dem iPhone: zu geht, was Pro öffnete, nicht was du schon geschrieben hast.",
        "landing.faq5q": "Und wenn ich schon Anki nutze?",
        "landing.faq5a": "Die Wiederholung von Micabo ist die von Anki: vier Tasten, dieselben Abstände, dieselben Stufen. Was Micabo dazugibt, macht Anki nicht: Blatt und Karten aus deinem Stoff schreiben, und den Plan um ein Prüfungsdatum ziehen. iPhone und Browser teilen denselben Plan: eine Karte, die hier wiederholt wurde, kommt dort nicht morgen wieder.",
