        "landing.faq1q": "¿Mis cursos son privados?",
        "landing.faq1a": "Sí. Tus cursos no están en un catálogo. Ya no hay un « Descubrir » donde un desconocido tropiece con tus fichas: es entre tú y tus amigos. Por defecto los ves solo. Puedes compartir uno al importar - con tus amigos, o con nadie - y se decide en ese instante, no después. El aislamiento está en la base: cada consulta se evalúa con tu identidad, no existe una consulta que pida los cursos de otra persona.",
        "landing.faq2q": "¿Micabo inventa cosas?",
        "landing.faq2a": "Es el riesgo que más nos tomamos en serio, porque una ficha falsa no parece un error. Una palabra mal leída puede dar una definición perfectamente creíble y completamente falsa. Micabo no define nunca un término del que no está seguro: si el contexto no basta, la palabra dudosa simplemente no aparece en la ficha.",
        "landing.faq3q": "¿Funciona en otros idiomas? ¿Otros sistemas escolares?",
        "landing.faq3a": "Sí. El país de estudios decide el sistema de referencia y el idioma de las fichas. El sitio se lee en inglés, francés, alemán, español o turco: cambias el idioma arriba de la página, en el recorrido o en ajustes. iPhone y navegador comparten el ajuste de las fichas.",
        "landing.faq4q": "¿Qué pasa al final de la prueba?",
        "landing.faq4a": "Los {days} días de prueba se acaban, y no se cobra nada si tú no lo has decidido. Tus cursos y tus tarjetas se quedan, en el sitio y en el iPhone: lo que se cierra es lo que Pro abría, no lo que ya has escrito.",
        "landing.faq5q": "¿Y si ya uso Anki?",
        "landing.faq5a": "La repetición espaciada de Micabo es la de Anki: cuatro botones, los mismos intervalos, los mismos peldaños. Lo que Micabo añade, Anki no lo hace: escribir la ficha y las tarjetas a partir de tu clase, y apretar el plan cuando pones la fecha de un examen. iPhone y navegador comparten la misma planificación: una tarjeta repasada de un lado no vuelve del otro al día siguiente.",
