        "demo.showcase.mathHeading": "Derivar un producto",
        "demo.showcase.mathParagraph": "La derivada de un producto **no** es el producto de las derivadas. Es el error más caro del capítulo, y se corrige aprendiendo la fórmula en el orden correcto.",
        "demo.showcase.mathCaption": "Se deriva uno, se conserva el otro — luego al revés.",
        "demo.showcase.mathStepsTitle": "Con un ejemplo",
        "demo.showcase.mathStep1": "Se pone u = x² y v = sin(x).",
        "demo.showcase.mathStep2": "Se deriva por separado: u' = 2x y v' = cos(x).",
        "demo.showcase.mathStep3": "Se junta: 2x·sin(x) + x²·cos(x).",
        "demo.showcase.mathCallout": "==El signo es un más, no un menos.== El menos solo aparece en la derivada de un **cociente**.",
