        "copy.audience": "{views, plural, one {# vista} other {# vistas}} · {adopts, plural, one {# añadido} other {# añadidos}}",
        "copy.practiceReview": "Repasar sin contar",
        "copy.practiceReviewHint": "Repasar sin contar · tus fechas no se mueven",
        "copy.heldBackNew": "{count, plural, one {# tarjeta nueva para más tarde — tu ritmo de hoy está alcanzado.} other {# tarjetas nuevas para más tarde — tu ritmo de hoy está alcanzado.}}",
        "copy.alreadySubscribed": "Ya estás suscrito.",
        "legal.backHome": "Volver al inicio",
        "legal.eyebrow": "Micabo · iPhone y sitio",
        "legal.updated": "Última actualización: {date}.",
        "legal.updatedDate": "2 de septiembre de 2026",
        "legal.privacy.metaTitle": "Privacidad",
        "legal.privacy.metaDescription": "Lo que Micabo retiene de usted, en el iPhone y en el sitio, y lo que puede hacer con ello.",
        "legal.privacy.heading": "Política de privacidad",
        "legal.privacy.linkLabel": "política de privacidad",
        "legal.privacy.intro1": "Esta política describe los datos que Micabo trata cuando utiliza el sitio [[site]] o la aplicación iPhone (identificador {bundle}). Ambos clientes comparten la misma cuenta y la misma base. También se aplica si aún no tiene cuenta y solo consulta el sitio.",
        "legal.privacy.intro2": "El responsable del tratamiento es {editor}, que edita Micabo. Para cualquier pregunta, corrección o supresión: [[contact]].",
        "legal.privacy.whatTitle": "Qué es Micabo",
        "legal.privacy.whatBody": "Micabo transforma un curso (PDF, foto, documento, vídeo) en una ficha y en flashcards, y las hace volver antes de que las olvide. Un modo examen aprieta las revisiones al acercarse una fecha. Puede compartir un curso con amigos o guardarlo para usted.",
        "legal.privacy.dataTitle": "Qué datos tratamos",
        "legal.privacy.dataAccount": "**La cuenta.** Dirección de correo, identificadores que proporcionan Apple o Google si elige esas conexiones, y un nombre de usuario. No almacenamos su contraseña: la conexión por correo se hace con un enlace, no con un secreto que guardaríamos.",
        "legal.privacy.dataSchool": "**El recorrido escolar.** País de estudios, nivel, asignaturas, centro si lo indica. Sirve para escribir la ficha en el idioma y el sistema adecuados, y para mostrarle a los compañeros del mismo centro si un curso está compartido.",
        "legal.privacy.dataCourses": "**Sus cursos.** Los archivos o enlaces que deposita, el texto extraído, las fichas y las tarjetas generadas, las imágenes de esquemas, los exámenes (nombre, fecha, nota objetivo) y el historial de revisión (cuándo vuelve una tarjeta, cómo la ha valorado).",
        "legal.privacy.dataFriends": "**Los amigos.** Las solicitudes de amistad, su lista de amigos y la visibilidad que pone en cada curso al importarlo: solo usted, sus amigos o los compañeros de su centro. No existe un catálogo público en el que un desconocido tropiece con sus fichas.",
        "legal.privacy.dataSubscription": "**La suscripción.** El estado de su acceso Pro (activo, prueba, cancelado), no el número de su tarjeta. El pago lo cobra Apple en el iPhone y Stripe en el sitio. RevenueCat sostiene el derecho, para que el iPhone y el navegador coincidan.",
        "legal.privacy.dataWaitlist": "**La lista de espera.** Si deja su dirección antes de tener cuenta, la guardamos para avisarle de la apertura, con la página de la que viene. No está ligada a una cuenta y no es visible desde la aplicación.",
        "legal.privacy.dataFeedback": "**Los comentarios.** Si envía un error o una idea desde la app, guardamos el mensaje, el tipo (error o idea) y el vínculo con su cuenta, para responder. Permanecen 24 meses y luego se borran. No sirven para perfilarle.",
        "legal.privacy.dataUsage": "**El uso de las generaciones.** Un contador por día y por función (ficha, tarjetas, explicación), sin el contenido del curso. Sirve para limitar abusos, no para perfilarle.",
        "legal.privacy.dataDirectory": "**El directorio.** Su nombre de usuario y, si lo ha indicado, su centro. Eso es lo que ve un amigo o un compañero, no su correo ni sus preferencias.",
        "legal.privacy.dataDevice": "**Lo que queda en el aparato.** En el iPhone, algunas piezas (imágenes de oclusión, audio de una tarjeta) pueden no salir nunca del teléfono. Las respuestas del recorrido de bienvenida quedan primero en el aparato y se escriben en la base una vez abierta la cuenta.",
        "legal.privacy.dataNoSell": "No vendemos sus datos. No mostramos publicidad. No entrenamos un modelo de lenguaje con sus cursos, salvo que un ajuste explícito lo proponga un día — y ese ajuste no existe hoy.",
        "legal.privacy.whyTitle": "Por qué los tratamos",
        "legal.privacy.whyLead": "Las bases jurídicas, en el sentido del RGPD:",
        "legal.privacy.whyContract": "**La ejecución del contrato** — crear la cuenta, importar un curso, escribir la ficha y las tarjetas, revisarlas, sincronizar iPhone y sitio, gestionar la suscripción.",
        "legal.privacy.whyLegitimate": "**El interés legítimo** — asegurar el servicio, impedir abusos, diagnosticar una avería, medir la audiencia del sitio de forma agregada y leer los comentarios que nos envía. Ese interés no pasa por delante del suyo: el aislamiento está en la base, no solo en la aplicación.",
        "legal.privacy.whyLegal": "**La obligación legal** — conservar lo que la facturación o la contabilidad exigen, el tiempo prescrito.",
        "legal.privacy.whyConsent": "**El consentimiento** — cuando elige compartir un curso, abrir la cámara o conectarse con Apple o Google.",
        "legal.privacy.accessTitle": "Quién tiene acceso",
        "legal.privacy.accessBody": "Sus cursos solo los puede leer usted, salvo que los haya compartido. Cada consulta a la base se evalúa con su identidad: no existe una consulta que pueda pedir los cursos de otra persona. Los comentarios que envía los lee el equipo, en [[contact]]. Nadie más tiene acceso desde la aplicación.",
        "legal.privacy.accessLead": "Algunos prestadores ven una parte de los datos, solo para prestar el servicio:",
        "legal.privacy.accessSupabase": "**Supabase** (Unión Europea, región Estocolmo) — cuenta, base, archivos.",
        "legal.privacy.accessVercel": "**Vercel** — alojamiento del sitio, registros técnicos (dirección IP, URL) y medición de audiencia: el número de páginas vistas, la página de la que viene, el país y el tipo de aparato, sin cookie y sin identificador que le siga. El tratamiento puede tener lugar fuera de la Unión Europea, bajo las cláusulas contractuales tipo del prestador.",
        "legal.privacy.accessApple": "**Apple y Google** — si se conecta con ellos o si paga en el App Store.",
        "legal.privacy.accessStripe": "**Stripe** — pago en el sitio.",
        "legal.privacy.accessRevenuecat": "**RevenueCat** — estado de la suscripción, compartido entre iPhone y sitio.",
        "legal.privacy.accessFal": "**fal.ai y los modelos que llama** (hoy, modelos de lenguaje, sobre todo de Google) — el texto o la imagen de su curso, el tiempo de escribir la ficha o las tarjetas. No tienen derecho a usarlos para otra cosa que esa generación.",
        "legal.privacy.accessYoutube": "**YouTube / Google** — si importa un vídeo, leemos sus metadatos y subtítulos.",
        "legal.privacy.accessTransfer": "Algunos de estos prestadores están establecidos fuera de la Unión Europea. La transferencia solo tiene entonces lugar para prestar el servicio, y se apoya en las garantías previstas por el RGPD (decisión de adecuación o cláusulas contractuales tipo del prestador).",
        "legal.privacy.cookiesTitle": "Cookies y rastreadores",
        "legal.privacy.cookiesWeb": "El sitio coloca las cookies necesarias para la sesión (reconocerle de una página a otra una vez conectado) y una cookie de preferencia de idioma de interfaz (`micabo.ui_locale`), guardada un año, que retiene el inglés, el francés, el alemán, el español o el turco. No colocamos cookie de medición de audiencia, ni de publicidad, ni de rastreo entre sitios. El sitio sí cuenta sus visitas, pero sin escribir nada en su aparato: la medición retiene una página vista, su procedencia, un país, un tipo de aparato, y nada que permita reconocerle de una visita a otra ni en otro sitio. Por eso no hay banner de consentimiento: no hay nada que rechazar de ese lado.",
        "legal.privacy.cookiesIos": "El iPhone no usa cookies. Guarda un token de sesión en el llavero del aparato.",
        "legal.privacy.retentionTitle": "Cuánto tiempo los guardamos",
        "legal.privacy.retentionWhile": "Mientras exista la cuenta. Los comentarios se van a más tardar a los 24 meses. Si la elimina, desde Ajustes en el sitio o en la app iPhone, o escribiéndonos, borramos el perfil, los cursos (incluido el texto extraído), las fichas, las tarjetas, el historial, los exámenes, las amistades, los contadores de uso, los comentarios y la dirección que haya dejado en la lista de espera.",
        "legal.privacy.retentionShared": "Un curso que ha compartido desaparece para sus amigos cuando lo elimina. Un amigo que ya ha revisado sus tarjetas conserva su propio historial, no su documento.",
        "legal.privacy.retentionAfter": "Tras la eliminación, queda en los prestadores lo que la ley o su contrato impone: facturas de Stripe o Apple, identificador de suscripción de RevenueCat, registros técnicos (Vercel, Supabase) unas semanas. fal.ai recibe el texto el tiempo de escribir la ficha; no le pedimos que lo conserve.",
        "legal.privacy.rightsTitle": "Sus derechos",
        "legal.privacy.rightsBody": "Puede acceder a sus datos, corregirlos, exportarlos, oponerse a un tratamiento o pedir la supresión. Para descargar una copia: Ajustes → «Descargar mis datos». Para borrar la cuenta: Ajustes → «Eliminar la cuenta», en el sitio o en la app iPhone. También puede escribir a [[contact]]. Respondemos en el plazo de un mes.",
        "legal.privacy.rightsCnil": "También puede presentar una reclamación ante la CNIL (cnil.fr).",
        "legal.privacy.minorsTitle": "Menores",
        "legal.privacy.minorsBody": "Micabo se dirige a estudiantes, también de bachillerato. No pedimos la fecha de nacimiento. Si tiene menos de quince años, el uso del servicio debe hacerse con el acuerdo de un titular de la patria potestad. No usamos los datos de un menor para publicidad ni para un perfilado comercial.",
        "legal.privacy.iosTitle": "El iPhone, además del sitio",
        "legal.privacy.iosBody": "La app puede pedir acceso a sus fotos o a la cámara para importar un curso. No es obligatorio: el sitio acepta un archivo depositado. Las notificaciones, si las autoriza, solo sirven para recordarle una revisión. La misma cuenta abre la app y el sitio.",
        "legal.privacy.changesTitle": "Modificaciones",
        "legal.privacy.changesBody": "Si esta política cambia de forma sustancial, actualizamos la fecha al inicio de la página. El uso continuado después de esa fecha vale para la nueva versión, salvo que la ley exija un acuerdo distinto.",
        "legal.privacy.changesAlso": "Las [[terms]] completan este texto.",
        "legal.terms.metaTitle": "Condiciones de uso",
        "legal.terms.metaDescription": "Las reglas del servicio Micabo, para el iPhone y el sitio: cuenta, cursos, suscripción, responsabilidades.",
        "legal.terms.heading": "Condiciones de uso",
        "legal.terms.linkLabel": "condiciones de uso",
        "legal.terms.intro1": "Estas condiciones rigen el uso de Micabo — el sitio [[site]] y la aplicación iPhone ({bundle}). Al crear una cuenta o al usar el servicio, las acepta. Si no está de acuerdo, no abra una cuenta.",
        "legal.terms.intro2": "El editor es {editor}. Contacto: [[contact]].",
        "legal.terms.serviceTitle": "El servicio",
        "legal.terms.serviceBody": "Micabo lee un documento de curso que usted deposita y escribe una ficha y flashcards. Las hace volver según una repetición espaciada (la misma regla SM-2 en el iPhone y en el sitio). Puede fijar la fecha de un examen: el plan de revisión se aprieta entonces hacia ese día. Una misma cuenta abre los dos clientes.",
        "legal.terms.servicePro": "Una parte del servicio es accesible sin suscripción. El acceso Pro (cursos y tarjetas más allá del techo gratuito, según la oferta mostrada en el momento de la compra) es de pago.",
        "legal.terms.accountTitle": "La cuenta",
        "legal.terms.accountBody": "Puede conectarse con Apple, Google o un enlace enviado por correo. Es responsable del acceso a su buzón y a esas cuentas de terceros. Una sola cuenta por persona.",
        "legal.terms.accountDelete": "Puede eliminar la cuenta desde Ajustes, en el sitio o en la app iPhone. Eso borra sus cursos, sus tarjetas y su historial. Las compras ya cobradas por Apple o Stripe siguen sujetas a sus reglas de reembolso.",
        "legal.terms.coursesTitle": "Sus cursos",
        "legal.terms.coursesOwn": "Usted conserva la propiedad de lo que deposita. Solo nos da el derecho, limitado y revocable, de leerlo, almacenarlo y transformarlo en ficha y en tarjetas, para prestarle el servicio — incluido enviarlo a un modelo de lenguaje el tiempo de la generación.",
        "legal.terms.coursesRights": "Solo deposita documentos que tiene derecho a usar. Un temario de su profesor, sus apuntes, un vídeo cuyo import está autorizado: sí. Una obra entera copiada, el trabajo de otro, un contenido ilegal: no. Podemos retirar un curso o cerrar una cuenta que rompa esta regla.",
        "legal.terms.coursesShare": "La visibilidad se decide al importar. Un curso privado se queda entre usted. Un curso compartido solo lo ven las personas que ha elegido (amigos o compañeros del centro). No es una biblioteca abierta a todos.",
        "legal.terms.notTitle": "Lo que Micabo no es",
        "legal.terms.notBody": "La ficha y las tarjetas se generan automáticamente. Pueden equivocarse, omitir un pasaje o leer mal un escaneo. Micabo no es un profesor ni una garantía de nota. Usted sigue siendo responsable de lo que aprende y de lo que entrega el día del examen.",
        "legal.terms.notInvent": "Nos esforzamos en no inventar una definición cuando el documento no la lleva. Eso no hace el resultado infalible.",
        "legal.terms.subTitle": "La suscripción",
        "legal.terms.subPrices": "Los precios, la duración y la prueba eventual son los mostrados antes del pago. Pueden cambiar para las compras nuevas; una suscripción ya en curso conserva sus condiciones hasta su renovación.",
        "legal.terms.subIos": "**En el iPhone**, el pago pasa por el App Store. La cancelación, la renovación y los reembolsos siguen las reglas de Apple. Gestione la suscripción en los ajustes de su cuenta Apple.",
        "legal.terms.subWeb": "**En el sitio**, el pago pasa por Stripe. La cancelación se hace desde el espacio de facturación indicado en el perfil, o escribiéndonos. Una prueba, si se ofrece, solo se convierte en pago si la deja llegar a su término.",
        "legal.terms.subBoth": "El acceso Pro comprado de un lado vale del otro: la misma cuenta es Pro en el iPhone y en el sitio. Un incidente de pago puede abrir un periodo de gracia; no cerramos el acceso a la primera hora.",
        "legal.terms.forbidTitle": "Lo que no hace",
        "legal.terms.forbidHarm": "Usar el servicio para perjudicar a alguien, acosar o hacer trampas de un modo que viole el reglamento de su centro.",
        "legal.terms.forbidAccess": "Intentar acceder a los cursos de otra cuenta, eludir el aislamiento o saturar el servicio a propósito.",
        "legal.terms.forbidResell": "Revender el acceso, extraer el servicio con un robot más allá de un uso humano normal, o copiar Micabo para hacer un producto competidor a partir de nuestras generaciones.",
        "legal.terms.forbidIllegal": "Depositar contenidos ilegales, de odio o que atenten contra la vida privada de terceros.",
        "legal.terms.availTitle": "Disponibilidad",
        "legal.terms.availBody": "Hacemos lo posible para que el iPhone y el sitio sigan accesibles. Un mantenimiento, una avería de un prestador (alojamiento, modelo, tienda) o un error de generación puede interrumpir el servicio. No ofrecemos garantía de resultado escolar ni de disponibilidad ininterrumpida.",
        "legal.terms.liabilityTitle": "Responsabilidad",
        "legal.terms.liabilityConsumer": "Si es consumidor, sus derechos legales (garantía, mediación, cláusulas abusivas) se aplican y estas condiciones no los apartan.",
        "legal.terms.liabilityLimit": "Más allá, Micabo no es responsable de las notas obtenidas, de una ficha incompleta, de un olvido el día D o de un daño indirecto (tiempo perdido, examen fallido). Nuestra responsabilidad, si se retuviera por un incumplimiento que nos sea imputable, se limita al importe que nos ha abonado en los últimos doce meses — salvo falta grave, dolo o lesión a la integridad de la persona.",
        "legal.terms.minorsTitle": "Menores",
        "legal.terms.minorsBody": "Si tiene menos de quince años, un titular de la patria potestad debe aceptar estas condiciones y vigilar el uso. Compartir un curso con amigos sigue bajo su responsabilidad y bajo la de ellos.",
        "legal.terms.lawTitle": "Derecho aplicable",
        "legal.terms.lawBody": "Estas condiciones se rigen por el derecho francés. En caso de litigio, y tras un intento de resolución por escrito a [[contact]], son competentes los tribunales franceses — sin perjuicio de las normas de protección del consumidor que le fueran más favorables.",
        "legal.terms.changesTitle": "Modificaciones",
        "legal.terms.changesBody": "Podemos actualizar estas condiciones. La fecha al inicio de la página es la que cuenta. Un cambio que afecte al precio de una suscripción en curso se le anuncia antes de la renovación.",
        "legal.terms.changesAlso": "La [[privacy]] describe el tratamiento de sus datos.",
        "articles.shared.navAria": "Páginas",
        "articles.shared.nextTitle": "Para leer después",
        "articles.shared.ctaTitle": "Deja un curso y mira en qué se convierte.",
        "articles.shared.ctaBody": "El primero es gratis, en el sitio y en el iPhone.",
        "articles.method.metaTitle": "El método: repetición espaciada y recuerdo activo",
        "articles.method.metaDescription": "Releer un curso no lo hace quedar. Lo que se recupera de memoria se queda, sobre todo si la pregunta vuelve justo antes de olvidarla. Cómo aplica Micabo la repetición espaciada, con los intervalos de verdad.",
        "articles.method.h1": "Releer no basta. Acordarse, sí.",
        "articles.method.lead1": "Una página releída cuatro veces da una impresión de dominio que no sobrevive al examen. Lo que avanza es el reconocimiento — « sí, esto ya lo he visto » — y el reconocimiento no es lo que pide un examen.",
        "articles.method.lead2": "Lo que se queda es lo que hubo que **sacar de memoria**, y lo que vuelve **justo antes de olvidarlo**. Dos ideas antiguas, medidas desde hace más de un siglo, y dos ideas pesadas de aplicar a mano. Ese es todo el trabajo de Micabo.",
        "articles.method.activeTitle": "El recuerdo activo: la pregunta antes que la respuesta",
        "articles.method.active1": "Ponerse a prueba es más eficaz que releer, incluso cuando uno se equivoca. El esfuerzo de recuperar es lo que refuerza la huella: una respuesta que se busca tres segundos vale más que una que se lee en uno.",
        "articles.method.active2": "Por eso una ficha lleva **una sola cosa que recuperar**. Una tarjeta que pide cinco elementos de golpe no se puede puntuar: se recuerdan tres, y no hay un botón para « tres quintos ».",
        "articles.method.spacingTitle": "El espaciado: volver en el último momento útil",
        "articles.method.spacing1": "Sin repaso, lo que se retiene de un curso cae a casi nada en un mes. Cada recuerdo pone el contador a cien — y la bajada que sigue es **más lenta que la anterior**. Repasar en el momento justo no pide más tiempo: pide menos, a medida que la memoria se estabiliza.",
        "articles.method.spacing2": "Lo que importa no es la forma de cada curva, es **el punto en que se separan**: el primer repaso. Lo que la repetición espaciada automatiza es la elección de ese instante, tarjeta a tarjeta.",
        "articles.method.plannerTitle": "Lo que Micabo calcula en cada nota",
        "articles.method.planner1": "Micabo planifica con **SM-2**, la regla de Anki en sus ajustes por defecto. Una tarjeta nueva pasa por peldaños cortos — {steps} — antes de salir a días. Luego cada nota multiplica el intervalo por una facilidad propia de la tarjeta, que parte de {ease} y se mueve según tus respuestas.",
        "articles.method.planner2": "Cuatro botones, no dos: « lo sé / no lo sé » no distingue la tarjeta recuperada con esfuerzo de la que vino sola, y es justo ese margen el que decide la fecha siguiente. Esto es lo que anuncian los cuatro botones en una tarjeta nueva:",
        "articles.method.planner3": "El intervalo está escrito en el botón **antes** de pulsar. Un planificador que decide a solas se desobedece pronto: se marca « fácil » para ir más rápido, la tarjeta se va tres semanas y se redescubre el día del examen.",
        "articles.method.stepMinutes": "{n} min",
        "articles.method.stepJoin": ", luego ",
        "articles.method.paceTitle": "El ritmo: minutos, no un cupo de tarjetas",
        "articles.method.pace1": "El ajuste que pide Micabo es un tiempo al día, no un número de tarjetas. A {minutes} minutos — el valor por defecto — se ven unas {seen} tarjetas, y el producto solo introduce **{perDay} nuevas**.",
        "articles.method.pace2": "La diferencia entre las dos es el núcleo del ajuste: una tarjeta nueva no cuesta un paso, cuesta unos {reps} antes de quedar. Meter cincuenta hoy porque hay tiempo es pedirse una deuda de sesiones para las tres semanas siguientes — y así se abandona un mazo.",
        "articles.method.paceNote": "El tope del día no bloquea los repasos debidos: esos pasan todos. Solo raciona la introducción de tarjetas nuevas. Un día perdido no abre un agujero, desplaza.",
        "articles.method.sheetTitle": "La ficha primero, las tarjetas después",
        "articles.method.sheet1": "Una flashcard supone que ya se ha entendido. Ponerse a prueba sobre una idea no leída es aprender de memoria una respuesta sin saber de qué habla — la tarjeta acertará, el examen no.",
        "articles.method.sheet2": "Por eso Micabo escribe primero **la ficha** a partir de tu documento: el curso en orden, los pasajes que importan marcados. Las tarjetas salen de esa ficha, no del documento bruto. Lees, luego te pones a prueba.",
        "articles.method.sheet3": "Micabo no define nunca un término del que el documento no hable. Cuando el contexto no decide, la palabra dudosa no aparece en la ficha: una definición inventada es perfectamente creíble, y por eso es peligrosa.",
        "articles.method.limitsTitle": "Lo que el método no hace",
        "articles.method.limits1": "La repetición espaciada coloca los repasos. No entiende por ti, no redacta un ensayo y no recupera un capítulo empezado la víspera: no hay espaciado posible en una noche.",
        "articles.method.limits2": "También ignora las fechas, por construcción: SM-2 no sabe que hay un examen dentro de tres semanas. Eso es exactamente lo que el [[exam]] viene a corregir.",
        "articles.method.examLink": "modo examen",
        "articles.exam.metaTitle": "El modo examen: das la fecha, el plan se aprieta",
        "articles.exam.metaDescription": "La repetición espaciada ignora el día D. El modo examen de Micabo le da una fecha tope, aprieta los pasos al acercarse la prueba e impide que una tarjeta se vaya más allá.",
        "articles.exam.h1": "Das la fecha. Micabo lo reorganiza todo.",
        "articles.exam.lead1": "La repetición espaciada coloca cada tarjeta en el último momento útil, sin fin. No sabe que hay un parcial el 14. Una tarjeta marcada « fácil » hoy se va tres semanas, aunque la prueba sea dentro de diez días — y no vuelve antes.",
        "articles.exam.lead2": "El modo examen da al planificador lo que le falta: **una fecha tope**. Pones el día D, él replanifica el mazo alrededor.",
        "articles.exam.trapTitle": "Por qué un plan normal se deja pillar",
        "articles.exam.trap1": "Un mazo de doscientas tarjetas en repetición espaciada es perfecto para un control continuo y malo para una fecha fija. Tres cosas se tuerce: unas tarjetas caen después del examen, otras nunca se introdujeron, y las más frágiles vuelven demasiado pronto para servir el día D.",
        "articles.exam.trap2": "La respuesta a mano es repasarlo todo la víspera. Es exactamente lo que el método evita: una sesión de trescientas tarjetas en una noche no deja nada al día siguiente, y se sabe antes de empezar.",
        "articles.exam.capTitle": "Ninguna tarjeta se va más allá del día D",
        "articles.exam.cap1": "Es la regla que lo sostiene todo, y es más radical de lo que parece. Durante un examen activo, el intervalo que recibe una tarjeta está **limitado a la fecha de la prueba**.",
        "articles.exam.cap2": "Sin ese tope, la primera respuesta buena deshace el plan: la tarjeta se va tres semanas y sale del campo. Con él, vuelve una última vez antes del día D. Los intervalos anunciados bajo los botones son por eso más cortos de lo habitual, y la sesión lo dice arriba — si no, parecería el planificador roto.",
        "articles.exam.planTitle": "El plan, anunciado antes de aplicarse",
        "articles.exam.plan1": "Micabo muestra la proyección **antes** de mover nada: cuántas tarjetas están cubiertas, cuántos pasos colocados, en cuántos días. Una replanificación que se descubre después es una que se cancela.",
        "articles.exam.plan2": "La carga se aprieta hacia el final sin amontonarse en la víspera: los últimos pasos se reparten en los {days} últimos días, desfasados de una tarjeta a otra.",
        "articles.exam.intensityTitle": "Tres intensidades, según la nota que quieres",
        "articles.exam.intensityLead": "Cuántas veces debe volver cada tarjeta antes de la prueba no es la misma pregunta para « quiero aprobar » y para « quiero la máxima ». Pones la nota objetivo, Micabo deduce la intensidad:",
        "articles.exam.intensityLight": "Ligera",
        "articles.exam.intensityStandard": "Normal",
        "articles.exam.intensityIntense": "Intensiva",
        "articles.exam.intensityPasses": "pasos por tarjeta",
        "articles.exam.intensityScale": "La escala de notas sigue tu país de estudios: un 20 francés, un 100 quebequés y un A-Level británico no se comparan, y un control que valiera en todas partes no valdría en ninguna.",
        "articles.exam.severalTitle": "Varios exámenes, varios cursos",
        "articles.exam.several1": "Un examen cubre los cursos que le das, y un curso puede estar en varios exámenes. Cuando dos fechas se disputan la misma tarjeta, **la más cercana** pone el tope: es la primera cota, y respetar la segunda primero fallaría las dos.",
        "articles.exam.severalNote": "Pasado el día D, el examen deja de forzar y el mazo vuelve a su planificación normal. Nada que desactivar: una fecha pasada ya no es una fecha.",
        "articles.exam.limitsTitle": "Lo que el modo examen no hace",
        "articles.exam.limits1": "No fabrica tiempo. Declarar un examen para mañana sobre doscientas tarjetas nuevas da un plan honesto e insostenible, y Micabo lo muestra tal cual en vez de tranquilizar.",
        "articles.exam.limits2": "Tampoco sustituye al método: [[method]] hacen el trabajo, el modo examen solo les da un plazo. Si vienes de Anki, la [[anki]] dice exactamente qué cambia.",
        "articles.exam.methodLink": "el recuerdo activo y el espaciado",
        "articles.exam.ankiLink": "comparación",
        "articles.anki.metaTitle": "Micabo o Anki: lo que cambia de verdad",
        "articles.anki.metaDescription": "Anki es gratis, abierto y excelente. Micabo escribe las tarjetas a partir de tu curso y replanifica todo alrededor de una fecha de examen. Comparación honesta, también donde Anki gana.",
        "articles.anki.eyebrow": "Comparación",
        "articles.anki.h1": "Micabo o Anki: lo que cambia de verdad",
        "articles.anki.lead1": "Anki es un muy buen programa. Es gratis, abierto, tiene veinte años de recorrido y una comunidad que lo ha documentado todo. Si ya lo usas y te vale, no tienes ninguna razón para cambiar.",
        "articles.anki.lead2": "La diferencia no está en la planificación — **es el mismo SM-2**. Está antes, en el tiempo que hace falta para tener tarjetas, y después, en lo que ocurre cuando cae una fecha de examen.",
        "articles.anki.tableTitle": "Línea a línea",
        "articles.anki.tableLead": "Tres líneas se las lleva Anki, entre ellas la más importante para mucha gente: no cuesta nada.",
        "articles.anki.tableCaption": "Comparación de Micabo y Anki, criterio a criterio.",
        "articles.anki.colCriterion": "Criterio",
        "articles.anki.rowAlgo": "El algoritmo",
        "articles.anki.rowAlgoMicabo": "SM-2, con los ajustes por defecto de Anki.",
        "articles.anki.rowAlgoAnki": "SM-2 históricamente, FSRS hoy, y los dos se ajustan.",
        "articles.anki.rowWrite": "Escribir las tarjetas",
        "articles.anki.rowWriteMicabo": "El curso se vuelve ficha, la ficha se vuelve tarjetas. Lees y corriges.",
        "articles.anki.rowWriteAnki": "A ti. Ahí se va la mayor parte del tiempo.",
        "articles.anki.rowDate": "Una fecha de examen",
        "articles.anki.rowDateMicabo": "El mazo se replanifica alrededor del día D, y nada se va más allá.",
        "articles.anki.rowDateAnki": "No hay idea de fecha tope. Se adelanta el mazo a mano.",
        "articles.anki.rowPrice": "El precio",
        "articles.anki.rowPriceMicabo": "Un curso gratis, {cards} tarjetas por sesión. Más allá, {price} al año.",
        "articles.anki.rowPriceAnki": "Gratis y de código abierto, salvo la app de iPhone.",
        "articles.anki.rowPlatforms": "Las plataformas",
        "articles.anki.rowPlatformsMicabo": "iPhone y navegador, la misma cuenta en los dos lados.",
        "articles.anki.rowPlatformsAnki": "Ordenador, Android, iPhone, navegador.",
        "articles.anki.rowDecks": "Los mazos ya hechos",
        "articles.anki.rowDecksMicabo": "Ningún catálogo. Tus cursos, y los que comparten tus amigos.",
        "articles.anki.rowDecksAnki": "Miles de mazos públicos, de calidad desigual.",
        "articles.anki.rowFriends": "Los cursos de tus compañeros",
        "articles.anki.rowFriendsMicabo": "Un curso compartido se retoma de un gesto y se vuelve tuyo.",
        "articles.anki.rowFriendsAnki": "Un archivo que hay que enviarse.",
        "articles.anki.rowStart": "La puesta en marcha",
        "articles.anki.rowStartMicabo": "Un documento dejado, una ficha que leer, una sesión esa misma noche.",
        "articles.anki.rowStartAnki": "Ajustes que entender antes de la primera tarjeta.",
        "articles.anki.costTitle": "El coste de Anki no es su precio",
        "articles.anki.cost1": "Un mazo de Anki útil para un curso de facultad son dos a cuatro horas de tecleo por capítulo: cortar, formular una pregunta por idea, no apilar cinco elementos en una tarjeta. Ese trabajo enseña — negarlo sería deshonesto — pero es el trabajo que hace que se abra Anki en septiembre y ya no en noviembre.",
        "articles.anki.cost2": "Micabo asume ese paso. El curso se vuelve una ficha ordenada, luego tarjetas sacadas de esa ficha. Lees, corriges lo falso, borras lo que no sirve. Sigue siendo tu trabajo, pero empieza en la relectura en vez de en la página en blanco.",
        "articles.anki.costNote": "El reverso es real: una tarjeta generada puede estar mal formulada o salir de un escaneo mal leído. Por eso la ficha va antes que las tarjetas, y Micabo no define un término del que el documento no habla. Una ficha que se equivoca no parece un error.",
        "articles.anki.dateTitle": "Lo que Anki no hace: la fecha",
        "articles.anki.date1": "Esa es la diferencia de mecánica de verdad. La repetición espaciada coloca cada tarjeta en el último momento útil, sin fin. No sabe que hay un parcial el 14: una tarjeta marcada « fácil » se va tres semanas y no vuelve antes de la prueba.",
        "articles.anki.date2": "En Anki se sale adelantando el mazo a mano, o repasándolo todo la víspera. En Micabo pones la fecha y el mazo se replanifica alrededor, con un tope que impide que una tarjeta se vaya más allá del día D. [[exam]] detalla cómo.",
        "articles.anki.examLink": "El modo examen",
        "articles.anki.pickTitle": "Cuál coger",
        "articles.anki.pickAnki": "**Quédate en Anki** si te gusta ajustar el planificador, si quieres FSRS, si estás en Android, o si quieres una herramienta gratis y abierta cuyos archivos te pertenecen.",
        "articles.anki.pickMicabo": "**Prueba Micabo** si lo que te frena no es el repaso sino fabricar las tarjetas, o si tus repasos giran en torno a fechas de examen y no a un flujo continuo.",
        "articles.anki.pickBoth": "Y si dudas: [[method]] es la misma en los dos. Es ella la que hace el trabajo, no el programa que la lleva.",
        "articles.anki.methodLink": "el método",
    ]

