        "landing.faq1q": "Derslerim gizli mi?",
        "landing.faq1a": "Evet. Derslerin bir katalogda durmaz. Yabancı birinin özetlerine denk geleceği bir « Keşfet » yok: bu seninle arkadaşların arasında. Varsayılan olarak yalnız sen görürsün. İçe aktarırken birini paylaşabilirsin - arkadaşlarınla, ya da kimseyle - ve karar o anda verilir, sonra değil. Ayrım veritabanında: her istek senin kimliğinle değerlendirilir, başkasının derslerini isteyen bir sorgu yoktur.",
        "landing.faq2q": "Micabo bir şeyler uyduruyor mu?",
        "landing.faq2a": "Bunu en ciddi dert ederiz, çünkü yanlış bir özet hataya benzemez. Kötü okunmuş bir sözcük, tamamen inandırıcı ve tamamen yanlış bir tanım verebilir. Micabo emin olmadığı bir terimi asla tanımlamaz: bağlam yetmezse kuşkulu sözcük özette görünmez.",
        "landing.faq3q": "Başka dillerde çalışır mı? Başka okul sistemlerinde?",
        "landing.faq3a": "Evet. Okuduğun ülke hem referans sistemini hem özetlerin dilini belirler. Site İngilizce, Fransızca, Almanca, İspanyolca veya Türkçe okunur: dili sayfanın üstünden, başlangıçta veya ayarlardan değiştirirsin. iPhone ve tarayıcı özet dilini paylaşır.",
        "landing.faq4q": "Deneme bitince ne olur?",
