        "copy.alreadySubscribed": "Zaten abonesin.",
        "legal.backHome": "Ana sayfaya dön",
        "legal.eyebrow": "Micabo · iPhone ve site",
        "legal.updated": "Son güncelleme: {date}.",
        "legal.updatedDate": "2 Eylül 2026",
        "legal.privacy.metaTitle": "Gizlilik",
        "legal.privacy.metaDescription": "Micabo'nun iPhone'da ve sitede sizden ne tuttuğu, ve bunlarla ne yapabileceğiniz.",
        "legal.privacy.heading": "Gizlilik politikası",
        "legal.privacy.linkLabel": "gizlilik politikası",
        "legal.privacy.intro1": "Bu politika, [[site]] sitesini veya iPhone uygulamasını (tanımlayıcı {bundle}) kullandığınızda Micabo'nun işlediği verileri anlatır. İki istemci aynı hesabı ve aynı veritabanını paylaşır. Henüz hesabınız yokken siteye bakıyorsanız da geçerlidir.",
        "legal.privacy.intro2": "Veri sorumlusu, Micabo'yu yayımlayan {editor}'dir. Soru, düzeltme veya silme için: [[contact]].",
        "legal.privacy.whatTitle": "Micabo nedir",
        "legal.privacy.whatBody": "Micabo bir dersi (PDF, fotoğraf, belge, video) özet kâğıdına ve kartlara dönüştürür, sonra unutmadan önce geri getirir. Sınav modu, bir tarihe yaklaşırken tekrarları sıkılaştırır. Bir dersi arkadaşlarınızla paylaşabilir veya kendinize saklayabilirsiniz.",
        "legal.privacy.dataTitle": "Hangi verileri işliyoruz",
        "legal.privacy.dataAccount": "**Hesap.** E-posta adresi, bu bağlantıları seçerseniz Apple veya Google'ın verdiği tanımlayıcılar ve bir kullanıcı adı. Parolanızı saklamıyoruz: e-posta ile giriş, saklayacağımız bir sırla değil, bir bağlantıyla yapılır.",
        "legal.privacy.dataSchool": "**Öğrenim yolu.** Öğrenim ülkesi, kademe, dersler, verirseniz okul. Özet kâğıdını doğru dilde ve doğru sistemde yazmak ve bir ders paylaşılmışsa aynı okuldaki arkadaşları göstermek için kullanılır.",
        "legal.privacy.dataCourses": "**Dersleriniz.** Yüklediğiniz dosyalar veya bağlantılar, bunlardan çıkarılan metin, üretilen özet kâğıtları ve kartlar, şema görselleri, sınavlar (ad, tarih, hedef not) ve tekrar geçmişi (bir kartın ne zaman döndüğü, nasıl puanladığınız).",
        "legal.privacy.dataFriends": "**Arkadaşlar.** Arkadaşlık istekleri, arkadaş listeniz ve içe aktarırken her derse koyduğunuz görünürlük: yalnızca siz, arkadaşlarınız veya okuldaki arkadaşlarınız. Bir yabancının özet kâğıtlarınıza rastlayacağı genel bir katalog yoktur.",
        "legal.privacy.dataSubscription": "**Abonelik.** Pro erişiminizin durumu (aktif, deneme, iptal), kart numaranız değil. Ödemeyi iPhone'da Apple, sitede Stripe alır. RevenueCat hakkı tutar, böylece iPhone ile tarayıcı aynı fikirde olur.",
        "legal.privacy.dataWaitlist": "**Bekleme listesi.** Hesabınız olmadan önce adresinizi bırakırsanız, açılışı haber vermek için geldiğiniz sayfayla birlikte saklarız. Bir hesaba bağlı değildir ve uygulamadan görünmez.",
        "legal.privacy.dataFeedback": "**Geri bildirimler.** Uygulamadan bir hata veya fikir gönderirseniz, yanıtlamak için iletiyi, türü (hata veya fikir) ve hesabınızla bağını saklarız. 24 ay kalır, sonra silinir. Sizi profillemek için kullanılmaz.",
        "legal.privacy.dataUsage": "**Üretimlerin kullanımı.** Günlük ve işlev başına bir sayaç (özet, kartlar, açıklama), dersin içeriği olmadan. Kötüye kullanımı sınırlamak içindir, sizi profillemek için değil.",
        "legal.privacy.dataDirectory": "**Rehber.** Kullanıcı adınız ve belirttiyseniz okulunuz. Bir arkadaşın veya okul arkadaşının gördüğü budur; e-postanız veya tercihleriniz değil.",
        "legal.privacy.dataDevice": "**Cihazda kalan.** iPhone'da bazı parçalar (örtme görselleri, bir kartın sesi) telefonu hiç terk etmeyebilir. Karşılama yolunun yanıtları önce cihazda kalır, hesap açılınca veritabanına yazılır.",
        "legal.privacy.dataNoSell": "Verilerinizi satmıyoruz. Reklam göstermiyoruz. Bir gün açık bir ayar bunu önermedikçe — ve bugün böyle bir ayar yoktur — dil modelini derslerinizle eğitmiyoruz.",
        "legal.privacy.whyTitle": "Neden işliyoruz",
        "legal.privacy.whyLead": "KVKK / GDPR anlamında hukuki dayanaklar:",
        "legal.privacy.whyContract": "**Sözleşmenin ifası** — hesabı oluşturmak, bir dersi içe aktarmak, özet kâğıdını ve kartları yazmak, tekrarlamak, iPhone ile siteyi eşitlemek, aboneliği yönetmek.",
        "legal.privacy.whyLegitimate": "**Meşru menfaat** — hizmeti güvenceye almak, kötüye kullanımı engellemek, bir arızayı teşhis etmek, sitenin kitlesini toplu biçimde ölçmek ve gönderdiğiniz geri bildirimleri okumak. Bu menfaat sizinkinin önüne geçmez: ayrıştırma uygulamada değil, veritabanındadır.",
        "legal.privacy.whyLegal": "**Yasal yükümlülük** — faturalama veya muhasebenin istediğini, öngörülen süre boyunca saklamak.",
        "legal.privacy.whyConsent": "**Rıza** — bir dersi paylaşmayı, kamerayı açmayı veya Apple ya da Google ile giriş yapmayı seçtiğinizde.",
        "legal.privacy.accessTitle": "Kim erişir",
        "legal.privacy.accessBody": "Derslerinizi, paylaşmadıysanız yalnızca siz okuyabilirsiniz. Veritabanına her istek kimliğinizle değerlendirilir: başkasının derslerini isteyebilecek bir sorgu yoktur. Gönderdiğiniz geri bildirimleri ekip [[contact]] adresinden okur. Uygulamadan başka kimsenin erişimi yoktur.",
        "legal.privacy.accessLead": "Hizmeti sağlamak için bazı yükleniciler verilerin bir kısmını görür:",
        "legal.privacy.accessSupabase": "**Supabase** (Avrupa Birliği, Stockholm bölgesi) — hesap, veritabanı, dosyalar.",
        "legal.privacy.accessVercel": "**Vercel** — sitenin barındırılması, teknik günlükler (IP adresi, URL) ve kitle ölçümü: görüntülenen sayfa sayısı, geldiğiniz sayfa, ülke ve cihaz türü; çerezsiz ve sizi izleyen bir tanımlayıcı olmadan. İşleme, yüklenicinin standart sözleşme maddeleri altında Avrupa Birliği dışında da olabilir.",
        "legal.privacy.accessApple": "**Apple ve Google** — onlarla giriş yaparsanız veya App Store'da öderseniz.",
        "legal.privacy.accessStripe": "**Stripe** — sitedeki ödeme.",
        "legal.privacy.accessRevenuecat": "**RevenueCat** — abonelik durumu, iPhone ile site arasında paylaşılır.",
        "legal.privacy.accessFal": "**fal.ai ve çağırdığı modeller** (bugün, özellikle Google'ın dil modelleri) — dersinizin metni veya görseli, özet kâğıdını veya kartları yazdığı süre. Bunları bu üretimden başka bir şey için kullanma hakları yoktur.",
        "legal.privacy.accessYoutube": "**YouTube / Google** — bir video içe aktarırsanız meta verilerini ve altyazılarını okuruz.",
        "legal.privacy.accessTransfer": "Bu yüklenicilerden bazıları Avrupa Birliği dışında kuruludur. Aktarım o zaman yalnızca hizmeti sağlamak için olur ve GDPR'nin öngördüğü güvencelere dayanır (yeterlilik kararı veya yüklenicinin standart sözleşme maddeleri).",
        "legal.privacy.cookiesTitle": "Çerezler ve izleyiciler",
        "legal.privacy.cookiesWeb": "Site, oturum için gerekli çerezleri (bağlandıktan sonra sizi bir sayfadan ötekine tanımak) ve bir yıl saklanan, İngilizce, Fransızca, Almanca, İspanyolca veya Türkçeyi tutan bir arayüz dili çerezi (`micabo.ui_locale`) koyar. Kitle ölçümü, reklam veya siteler arası izleme çerezi koymuyoruz. Site ziyaretlerini elbette sayıyor, ama cihazınıza hiçbir şey yazmadan: ölçüm bir sayfa görüntülemesini, nereden geldiğini, bir ülkeyi ve bir cihaz türünü tutar; sizi bir ziyaretten ötekine ya da başka bir sitede tanımaya yarayacak hiçbir şeyi tutmaz. Bu yüzden bir onay şeridi yoktur: o tarafta reddedecek bir şey yoktur.",
        "legal.privacy.cookiesIos": "iPhone çerez kullanmaz. Oturum jetonunu cihazın anahtarlığında tutar.",
        "legal.privacy.retentionTitle": "Ne kadar saklarız",
        "legal.privacy.retentionWhile": "Hesap durduğu sürece. Geri bildirimler en geç 24 ayda gider. Sitede veya iPhone uygulamasında Ayarlar'dan, ya da bize yazarak silerseniz profili, dersleri (çıkarılan metin dahil), özet kâğıtlarını, kartları, geçmişi, sınavları, arkadaşlıkları, kullanım sayaçlarını, geri bildirimleri ve bekleme listesinde bırakılmış adresi sileriz.",
        "legal.privacy.retentionShared": "Paylaştığınız bir ders, sildiğinizde arkadaşlarınız için kaybolur. Kartlarınızı zaten tekrarlamış bir arkadaş kendi geçmişini tutar, belgenizi değil.",
        "legal.privacy.retentionAfter": "Silmeden sonra yüklenicilerde yasanın veya sözleşmelerinin istediği kalır: Stripe veya Apple faturaları, RevenueCat abonelik tanımlayıcısı, teknik günlükler (Vercel, Supabase) birkaç hafta. fal.ai metni özet kâğıdını yazdığı süre alır; saklamasını istemeyiz.",
        "legal.privacy.rightsTitle": "Haklarınız",
        "legal.privacy.rightsBody": "Verilerinize erişebilir, düzeltebilir, dışa aktarabilir, bir işlemeye itiraz edebilir veya silinmesini isteyebilirsiniz. Bir kopya indirmek için: Ayarlar → «Verilerimi indir». Hesabı silmek için: Ayarlar → «Hesabı sil», sitede veya iPhone uygulamasında. [[contact]] adresine de yazabilirsiniz. Bir ay içinde yanıtlarız.",
        "legal.privacy.rightsCnil": "CNIL'e de şikâyet başvurabilirsiniz (cnil.fr).",
        "legal.privacy.minorsTitle": "Reşit olmayanlar",
        "legal.privacy.minorsBody": "Micabo öğrencilere, lise dahil, yöneliktir. Doğum tarihi sormuyoruz. On beş yaşından küçükseniz hizmet, velayet sahibinin onayıyla kullanılmalıdır. Bir küçüğün verilerini reklam veya ticari profilleme için kullanmayız.",
        "legal.privacy.iosTitle": "iPhone, sitenin yanı sıra",
        "legal.privacy.iosBody": "Uygulama, bir dersi içe aktarmak için fotoğraflarınıza veya kameraya erişim isteyebilir. Zorunlu değildir: site yüklenen bir dosyayı kabul eder. İzin verirseniz bildirimler yalnızca bir tekrarı hatırlatır. Aynı hesap uygulamayı ve siteyi açar.",
        "legal.privacy.changesTitle": "Değişiklikler",
        "legal.privacy.changesBody": "Bu politika esaslı biçimde değişirse sayfa başındaki tarihi güncelleriz. Bu tarihten sonraki sürekli kullanım, yasa ayrı bir onay istemedikçe, yeni sürüm için geçerlidir.",
        "legal.privacy.changesAlso": "[[terms]] bu metni tamamlar.",
        "legal.terms.metaTitle": "Kullanım koşulları",
        "legal.terms.metaDescription": "Micabo hizmetinin iPhone ve site için kuralları: hesap, dersler, abonelik, sorumluluklar.",
        "legal.terms.heading": "Kullanım koşulları",
        "legal.terms.linkLabel": "kullanım koşulları",
        "legal.terms.intro1": "Bu koşullar Micabo'nun kullanımını düzenler — [[site]] sitesi ve iPhone uygulaması ({bundle}). Hesap açarak veya hizmeti kullanarak bunları kabul edersiniz. Katılmıyorsanız hesap açmayın.",
        "legal.terms.intro2": "Yayımcı {editor}'dir. İletişim: [[contact]].",
        "legal.terms.serviceTitle": "Hizmet",
        "legal.terms.serviceBody": "Micabo yüklediğiniz bir ders belgesini okur ve bir özet kâğıdı ile kartlar yazar. Bunları aralıklı tekrar ile geri getirir (iPhone'da ve sitede aynı SM-2 kuralı). Bir sınav tarihi koyabilirsiniz: tekrar planı o güne doğru sıkılaşır. Aynı hesap iki istemciyi de açar.",
        "legal.terms.servicePro": "Hizmetin bir kısmı abonelik olmadan açıktır. Pro erişim (satın alma anında gösterilen teklife göre ücretsiz tavanın ötesindeki dersler ve kartlar) ücretlidir.",
        "legal.terms.accountTitle": "Hesap",
        "legal.terms.accountBody": "Apple, Google veya e-posta ile gönderilen bir bağlantıyla giriş yapabilirsiniz. Posta kutunuza ve bu üçüncü taraf hesaplara erişimden siz sorumlusunuz. Kişi başına bir hesap.",
        "legal.terms.accountDelete": "Hesabı Ayarlar'dan silebilirsiniz, sitede veya iPhone uygulamasında. Bu, derslerinizi, kartlarınızı ve geçmişinizi siler. Apple veya Stripe'ın zaten aldığı alışlar, onların iade kurallarına bağlı kalır.",
        "legal.terms.coursesTitle": "Dersleriniz",
        "legal.terms.coursesOwn": "Yüklediğinizin mülkiyeti sizde kalır. Bize yalnızca, hizmeti sunmak için — üretim süresi boyunca bir dil modeline göndermek dahil — okuma, saklama ve özet kâğıdı ile kartlara dönüştürme konusunda sınırlı ve geri alınabilir bir hak verirsiniz.",
        "legal.terms.coursesRights": "Yalnızca kullanma hakkınız olan belgeler yüklersiniz. Öğretmeninizin ders notu, kendi notlarınız, içe aktarımı izinli bir video: evet. Baştan sona kopyalanmış bir eser, başkasının ödevi, yasadışı içerik: hayır. Bu kuralı bozan bir dersi kaldırabilir veya bir hesabı kapatabiliriz.",
        "legal.terms.coursesShare": "Görünürlük içe aktarmada kararlaştırılır. Özel bir ders sizde kalır. Paylaşılan bir dersi yalnızca seçtiğiniz kişiler (arkadaşlar veya okuldaki arkadaşlar) görür. Herkese açık bir kütüphane değildir.",
        "legal.terms.notTitle": "Micabo ne değildir",
        "legal.terms.notBody": "Özet kâğıdı ve kartlar otomatik üretilir. Yanılabilir, bir pasajı atlayabilir veya bir taramayı yanlış okuyabilir. Micabo bir öğretmen değildir, not garantisi de değildir. Öğrendiğinizden ve sınav günü teslim ettiğinizden siz sorumlusunuz.",
        "legal.terms.notInvent": "Belge taşımıyorsa bir tanım uydurmamaya çalışırız. Bu, sonucu yanılmaz yapmaz.",
        "legal.terms.subTitle": "Abonelik",
        "legal.terms.subPrices": "Fiyatlar, süre ve varsa deneme, ödemeden önce gösterilenlerdir. Yeni alışlar için değişebilir; süren bir abonelik yenilenene kadar kendi koşullarını korur.",
        "legal.terms.subIos": "**iPhone'da** ödeme App Store üzerinden geçer. İptal, yenileme ve iadeler Apple'ın kurallarını izler. Aboneliği Apple hesabınızın ayarlarından yönetin.",
        "legal.terms.subWeb": "**Sitede** ödeme Stripe üzerinden geçer. İptal, profilde belirtilen fatura alanından veya bize yazarak yapılır. Önerilirse bir deneme, sonuna bırakırsanız ancak o zaman ödemeye dönüşür.",
        "legal.terms.subBoth": "Bir tarafta alınan Pro erişim ötekinde de geçerlidir: aynı hesap iPhone'da ve sitede Pro'dur. Bir ödeme aksaması bir ek süre açabilir; erişimi ilk saatte kapatmayız.",
        "legal.terms.forbidTitle": "Yapmadıklarınız",
        "legal.terms.forbidHarm": "Hizmeti birine zarar vermek, taciz etmek veya okulunuzun yönetmeliğini ihlal eden bir şekilde kopya çekmek için kullanmak.",
        "legal.terms.forbidAccess": "Başka bir hesabın derslerine erişmeye, ayrıştırmayı aşmaya veya hizmeti bile isteye yormaya çalışmak.",
        "legal.terms.forbidResell": "Erişimi satmak, hizmeti normal insan kullanımının ötesinde bir robotla çekmek veya üretimlerimizden rakip bir ürün yapmak için Micabo'yu kopyalamak.",
        "legal.terms.forbidIllegal": "Yasadışı, nefret içeren veya başkasının özel hayatına zarar veren içerik yüklemek.",
        "legal.terms.availTitle": "Erişilebilirlik",
        "legal.terms.availBody": "iPhone ve sitenin ulaşılabilir kalması için elimizden geleni yaparız. Bir bakım, bir yüklenici arızası (barındırma, model, mağaza) veya bir üretim hatası hizmeti kesebilir. Okul sonucu veya kesintisiz erişilebilirlik garantisi vermiyoruz.",
        "legal.terms.liabilityTitle": "Sorumluluk",
        "legal.terms.liabilityConsumer": "Tüketicisiyseniz yasal haklarınız (garanti, arabuluculuk, haksız hükümler) geçerlidir ve bu koşullar onları ortadan kaldırmaz.",
        "legal.terms.liabilityLimit": "Bunun ötesinde Micabo alınan notlardan, eksik bir özet kâğıdından, sınav günü unutulan bir şeyden veya dolaylı bir zarardan (kayıp zaman, kaçırılan sınav) sorumlu değildir. Bize yüklenebilir bir yükümlülük ihlali için sorumluluğumuz tutulursa, son on iki ayda bize ödediğiniz tutarla sınırlıdır — ağır kusur, kast veya kişi dokunulmazlığına saldırı hariç.",
        "legal.terms.minorsTitle": "Reşit olmayanlar",
        "legal.terms.minorsBody": "On beş yaşından küçükseniz bir velayet sahibi bu koşulları kabul etmeli ve kullanımı izlemelidir. Bir dersi arkadaşlarla paylaşmak sizin ve onların sorumluluğunda kalır.",
        "legal.terms.lawTitle": "Uygulanacak hukuk",
        "legal.terms.lawBody": "Bu koşullar Fransız hukukuna tabidir. Uyuşmazlıkta ve [[contact]] adresine yazılı bir çözüm denemesinden sonra Fransız mahkemeleri yetkilidir — size daha elverişli olacak tüketici koruma kuralları saklıdır.",
        "legal.terms.changesTitle": "Değişiklikler",
        "legal.terms.changesBody": "Bu koşulları güncelleyebiliriz. Sayfa başındaki tarih geçerlidir. Süregelen bir aboneliğin fiyatını ilgilendiren bir değişiklik, yenilemeden önce size duyurulur.",
        "legal.terms.changesAlso": "[[privacy]] verilerinizin işlenmesini anlatır.",
        "articles.shared.navAria": "Sayfalar",
        "articles.shared.nextTitle": "Sırada oku",
        "articles.shared.ctaTitle": "Bir ders bırak, neye dönüştüğüne bak.",
        "articles.shared.ctaBody": "İlki ücretsiz, sitede de iPhone'da da.",
        "articles.method.metaTitle": "Yöntem: aralıklı tekrar ve aktif hatırlama",
        "articles.method.metaDescription": "Bir dersi yeniden okumak onu akılda tutmaz. Bellekten çıkarman gereken kalır — soru unutmadan hemen önce geri gelirse hele. Micabo aralıklı tekrarı gerçek aralıklarla nasıl uygular.",
        "articles.method.h1": "Yeniden okumak yetmez. Hatırlamak yeter.",
        "articles.method.lead1": "Dört kez okunan bir sayfa, sınava kadar dayanamayan bir hâkimiyet hissi verir. İlerleyen tanımadır — « evet, bunu daha önce gördüm » — ve tanıma, bir sınavın sorduğu şey değildir.",
        "articles.method.lead2": "Tutan, **bellekten çıkarmak** zorunda kaldığın ve **unutmadan hemen önce** geri gelen şeydir. İki eski fikir, bir yüzyıldan fazladır ölçülmüş, elle uygulanması zahmetli. Micabo'nun bütün işi bu.",
        "articles.method.activeTitle": "Aktif hatırlama: yanıttan önce soru",
        "articles.method.active1": "Kendini sınamak, yeniden okumaktan daha etkilidir — yanıldığında bile. İzi güçlendiren, geri getirme çabasıdır: üç saniye aranan bir yanıt, bir saniyede okunandan değerlidir.",
        "articles.method.active2": "Bir kartın **hatırlanacak tek bir şey** taşımasının nedeni de budur. Bir anda beş öğe soran bir kart notlanamaz: üçünü hatırlarsın, « beşte üç » düğmesi yoktur.",
        "articles.method.spacingTitle": "Aralık: son yararlı anda geri gelmek",
        "articles.method.spacing1": "Tekrar olmadan, bir dersten kalan bir ayda neredeyse yok olur. Her hatırlatma sayacı yüze çeker — ve sonraki iniş **öncekinden daha yavaştır**. Doğru anda tekrar etmek daha fazla zaman istemez: bellek oturdukça daha az ister.",
        "articles.method.spacing2": "Önemli olan her eğrinin biçimi değil, **ayrıldıkları yerdir**: ilk tekrar. Aralıklı tekrarın otomatikleştirdiği, kart kart bu anın seçimidir.",
        "articles.method.plannerTitle": "Micabo her notta ne hesaplar",
        "articles.method.planner1": "Micabo **SM-2** ile planlar, Anki'nin varsayılan kuralıdır. Yeni bir kart kısa basamaklardan — {steps} — geçer, sonra günlere çıkar. Sonra her not, {ease} ile başlayan ve yanıtlarına göre kımıldayan bir kolaylıkla aralığı çarpar.",
        "articles.method.planner2": "Dört düğme, iki değil: « biliyorum / bilmiyorum » zor hatırlanan kartı kendiliğinden gelenden ayırmaz — sonraki tarihi de tam bu fark kararlaştırır. Yeni bir kartta dört düğmenin duyurduğu budur:",
        "articles.method.planner3": "Aralık, basmadan **önce** düğmenin üstündedir. Kendi köşesinde karar veren bir planlayıcıya çabuk uyulmaz: hızlanmak için « kolay » dersin, kart üç hafta gider, sınav günü yeniden keşfedersin.",
        "articles.method.stepMinutes": "{n} dk",
        "articles.method.stepJoin": ", sonra ",
        "articles.method.paceTitle": "Tempo: dakika, kart kotası değil",
        "articles.method.pace1": "Micabo'nun sorduğu, günde bir süre, kart sayısı değil. {minutes} dakikada — varsayılan — yaklaşık {seen} kart görürsün, ürün yalnız **{perDay} yeni** kart sokar.",
        "articles.method.pace2": "İkisinin arası ayarın özüdür: yeni bir kart bir geçiş değil, oturana kadar yaklaşık {reps} geçiş eder. Bugün vakit var diye elli kart sokmak, sonraki üç haftaya oturum borcu yazmaktır — bir destenin bırakılışı da böyle olur.",
        "articles.method.paceNote": "Günün tavanı vadesi gelen tekrarları durdurmaz: hepsi geçer. Yalnız yeni kartların girişini kısıtlar. Kaçırılan bir gün delik açmaz, kaydırır.",
        "articles.method.sheetTitle": "Önce özet kâğıdı, sonra kartlar",
        "articles.method.sheet1": "Bir flashcard, anlamış olmayı varsayar. Okumadığın bir fikri sınamak, neyden söz ettiğini bilmeden bir yanıt ezberlemektir — kart tutar, sınav tutmaz.",
        "articles.method.sheet2": "Bu yüzden Micabo belgenden önce **özet kâğıdını** yazar: ders sıraya konur, önemli yerler işaretlenir. Kartlar bu kâğıttan çıkar, ham belgeden değil. Okursun, sonra kendini sınarsın.",
        "articles.method.sheet3": "Micabo, belgenin konuşmadığı bir terimi asla tanımlamaz. Bağlam karar vermezse kuşkulu söz kâğıtta görünmez: uydurma bir tanım inandırıcıdır, tehlikeli olmasının nedeni de budur.",
        "articles.method.limitsTitle": "Yöntemin yapmadığı",
        "articles.method.limits1": "Aralıklı tekrar, tekrarları yerleştirir. Senin yerine anlamaz, kompozisyon yazmaz, dün başlanan bir bölümü kurtarmaz — bir gecelik aralık yoktur.",
        "articles.method.limits2": "Tarihleri de, yapısı gereği, umursamaz: SM-2 üç hafta sonra sınav olduğunu bilmez. [[exam]] tam bunu düzeltir.",
        "articles.method.examLink": "sınav kipi",
        "articles.exam.metaTitle": "Sınav kipi: tarihi ver, plan sıkışır",
        "articles.exam.metaDescription": "Aralıklı tekrar J gününü bilmez. Micabo'nun sınav kipi ona bir son tarih verir, geçişleri sınava yaklaştıkça sıkıştırır ve hiçbir kartın ötesine gitmesine izin vermez.",
        "articles.exam.h1": "Tarihi sen ver. Micabo her şeyi yeniden dizer.",
        "articles.exam.lead1": "Aralıklı tekrar her kartı son yararlı ana koyar, sonsuza dek. 14'ünde vize olduğunu bilmez. Bugün « kolay » notlanan bir kart üç hafta gider — sınav on gün sonra olsa bile — ve daha önce dönmez.",
        "articles.exam.lead2": "Sınav kipi planlayıcıya eksiğini verir: **bir son tarih**. J gününü koyarsın, desteyi onun etrafında yeniden planlar.",
        "articles.exam.trapTitle": "Sıradan bir plan neden tuzağa düşer",
        "articles.exam.trap1": "Aralıklı tekrardaki iki yüz kartlık bir deste sürekli kontrol için iyidir, sabit bir tarih için kötüdür. Üç şey bozulur: kartlar sınavdan sonra düşer, bazıları hiç sokulmamıştır, en kırılganlar J gününde işe yaramayacak kadar erken döner.",
        "articles.exam.trap2": "Elle çözüm, destenin hepsini akşamdan tekrar etmektir. Yöntemin kaçındığı tam budur: bir gecede üç yüz kart, ertesi güne bir şey bırakmaz — ve bunu başlamadan bilirsin.",
        "articles.exam.capTitle": "Hiçbir kart J gününün ötesine gitmez",
        "articles.exam.cap1": "Her şeyi tutan kural budur ve göründüğünden daha keskindir. Etkin bir sınavda bir kartın aldığı aralık **sınav tarihine tavanlanır**.",
        "articles.exam.cap2": "Bu tavan olmadan ilk doğru yanıt planı bozar: kart üç hafta gider, alandan çıkar. Onunla, J gününden önce bir kez daha döner. Düğmelerin altındaki aralıklar bu yüzden her zamankinden kısadır ve oturum bunu tepede söyler — yoksa planlayıcı bozuk sanılır.",
        "articles.exam.planTitle": "Plan, uygulanmadan önce duyurulur",
        "articles.exam.plan1": "Micabo projeksiyonu bir şeyi **kaydırmadan önce** gösterir: kaç kart kapsandı, kaç geçiş kondu, kaç güne yayıldı. Sonradan keşfedilen bir yeniden planlama, iptal edilen bir yeniden planlamadır.",
        "articles.exam.plan2": "Yük sona doğru sıkışır, akşamüstüne yığılmaz: son geçişler son {days} güne yayılır, karttan karta kaydırılır.",
        "articles.exam.intensityTitle": "Üç yoğunluk, istediğin nota göre",
        "articles.exam.intensityLead": "Her kartın sınavdan önce kaç kez geçeceği, « geçmek istiyorum » ile « birincilik istiyorum » için aynı soru değildir. Hedef notu koyarsın, Micabo yoğunluğu çıkarır:",
        "articles.exam.intensityLight": "Hafif",
        "articles.exam.intensityStandard": "Normal",
        "articles.exam.intensityIntense": "Yoğun",
        "articles.exam.intensityPasses": "kart başına geçiş",
        "articles.exam.intensityScale": "Not ölçeği okuduğun ülkeyi izler: Fransız 20'si, Quebec 100'ü ve Britanya A-Level'ı kıyaslanmaz — her yerde geçerli bir kaydırıcı hiçbir yerde bir şey demez.",
        "articles.exam.severalTitle": "Birden fazla sınav, birden fazla ders",
        "articles.exam.several1": "Bir sınav, ona verdiğin dersleri kapsar; bir ders birkaç sınavda olabilir. İki tarih aynı kartı çekişirse tavanı **daha yakın olan** koyar: ilk kısıt odur, ikincisine önce uymak ikisini de kaçırır.",
        "articles.exam.severalNote": "J günü geçince sınav zorlamayı bırakır, deste normal planına döner. Kapatılacak bir şey yoktur: geçmiş bir tarih artık tarih değildir.",
        "articles.exam.limitsTitle": "Sınav kipinin yapmadığı",
        "articles.exam.limits1": "Zaman üretmez. Yarın için iki yüz yeni kartlık bir sınav, dürüst ve tutulamaz bir plan verir — Micabo teselli etmek yerine onu olduğu gibi gösterir.",
        "articles.exam.limits2": "Yöntemin yerini de almaz: işi [[method]] yapar, sınav kipi onlara yalnız bir süre verir. Anki'den geliyorsan [[anki]] tam olarak neyin değiştiğini söyler.",
        "articles.exam.methodLink": "aktif hatırlama ve aralık",
        "articles.exam.ankiLink": "karşılaştırma",
        "articles.anki.metaTitle": "Micabo ya da Anki: asıl değişen",
        "articles.anki.metaDescription": "Anki ücretsiz, açık ve çok iyidir. Micabo kartları dersinden yazar ve her şeyi bir sınav tarihinin etrafında yeniden planlar. Dürüst karşılaştırma — Anki'nin kazandığı yerler dahil.",
        "articles.anki.eyebrow": "Karşılaştırma",
        "articles.anki.h1": "Micabo ya da Anki: asıl değişen",
        "articles.anki.lead1": "Anki çok iyi bir yazılımdır. Ücretsizdir, açıktır, yirmi yıllık mesafesi ve her şeyi belgelemiş bir topluluğu vardır. Zaten kullanıyorsan ve işine geliyorsa değiştirmek için bir nedenin yoktur.",
        "articles.anki.lead2": "Fark planlamada değildir — **aynı SM-2'dir**. Öndedir, kartlara sahip olmanın sürdüğü zamanda; ve arkadadır, bir sınav tarihi düşünce olan bitende.",
