        "articles.anki.date2": "Anki'de desteyi elle öne alarak veya akşamdan hepsini tekrar ederek idare edilir. Micabo'da tarihi koyarsın, deste etrafında yeniden planlanır; bir tavan kartın J gününün ötesine gitmesini engeller. Nasıl olduğunu [[exam]] anlatır.",
